// Neue Fragentypen (tf, multi, order, match, …) – Format: siehe content.js
export default {
  "fernabsatz-ecommerce": [
    {
      type: "tf", level: 1, correct: true,
      de: { q: "E-Commerce ist eine besondere Form des Fernabsatzes.", e: "Beim E-Commerce läuft der ganze Handel über das Internet – also über ein Fernkommunikationsmittel. Damit ist jeder E-Commerce-Kauf auch Fernabsatz, aber nicht jeder Fernabsatz (z. B. Katalog, Telefon) ist E-Commerce." },
      en: { q: "E-commerce is a special form of distance selling.", e: "In e-commerce the whole trade takes place over the internet, i.e. a means of distance communication. So every e-commerce purchase is distance selling, but not all distance selling (e.g. catalogue, phone) is e-commerce." },
      hu: { q: "Az e-kereskedelem a távértékesítés egyik különleges formája.", e: "Az e-kereskedelemben az egész ügylet az interneten, vagyis távközlési eszközön keresztül zajlik. Ezért minden e-kereskedelmi vásárlás távértékesítés is, de nem minden távértékesítés (pl. katalógus, telefon) e-kereskedelem." },
    },
    {
      type: "tf", level: 3, correct: false,
      de: { q: "Verhandelt eine Kundin im Geschäft über den Preis und schließt den Kauf am nächsten Tag telefonisch ab, liegt ein Fernabsatzgeschäft vor.", e: "Falsch: Fernabsatz liegt nur vor, wenn ALLE Phasen ausschließlich über Fernkommunikationsmittel laufen. Wurde vorher persönlich im Geschäft verhandelt, ist es kein Fernabsatz – auch wenn der Abschluss per Telefon erfolgt." },
      en: { q: "If a customer negotiates the price in the shop and concludes the purchase by phone the next day, it is a distance contract.", e: "False: distance selling requires ALL phases to take place exclusively via means of distance communication. If the parties negotiated in person in the shop first, it is not distance selling – even if the contract is concluded by phone." },
      hu: { q: "Ha egy vevő az üzletben alkudozik az árról, majd másnap telefonon köti meg a vásárlást, akkor távértékesítésről van szó.", e: "Hamis: távértékesítésről csak akkor beszélünk, ha MINDEN szakasz kizárólag távközlési eszközökön keresztül zajlik. Ha előtte személyesen tárgyaltak az üzletben, az nem távértékesítés – még akkor sem, ha a szerződést telefonon kötik meg." },
    },
    {
      type: "tf", level: 1, correct: true,
      de: { q: "Die AGB eines Onlineshops müssen schon vor der Bestellung leicht auffindbar sein.", e: "Richtig: Das gehört zur Informationspflicht. AGB, die man erst auf Nachfrage oder nach dem Kauf zu sehen bekommt, können gar nicht Vertragsinhalt werden." },
      en: { q: "An online shop's terms and conditions must be easy to find before the order is placed.", e: "True: this is part of the duty to inform. Terms that customers only see on request or after the purchase cannot become part of the contract at all." },
      hu: { q: "Egy webáruház ÁSZF-ének már a megrendelés előtt könnyen megtalálhatónak kell lennie.", e: "Igaz: ez a tájékoztatási kötelezettség része. Az az ÁSZF, amelyet a vevő csak kérésre vagy a vásárlás után lát, egyáltalán nem válhat a szerződés részévé." },
    },
    {
      type: "multi", level: 2, correct: [0, 1, 2, 4],
      de: { q: "Worüber muss ein Onlineshop seine Kund:innen VOR Vertragsabschluss informieren? Wähle alle zutreffenden Angaben.", o: ["Wesentliche Eigenschaften des Produkts", "Preis inklusive Steuern", "Rücktrittsrecht", "Einkaufspreis beim eigenen Lieferanten", "Gewährleistung", "Anzahl der Mitarbeiter:innen im Lager"], e: "Vor Vertragsabschluss muss der Verkäufer über Produkteigenschaften, Preis inkl. Steuern, Lieferung/Zahlung, Rücktrittsrecht und Gewährleistung informieren. Einkaufspreise oder interne Daten wie die Personalanzahl sind Geschäftsgeheimnisse und keine Pflichtangaben." },
      en: { q: "What must an online shop inform its customers about BEFORE the contract is concluded? Select all that apply.", o: ["Main characteristics of the product", "Price including taxes", "Right of withdrawal", "Purchase price paid to its own supplier", "Statutory warranty", "Number of warehouse staff"], e: "Before the contract the seller must inform about product characteristics, price incl. taxes, delivery/payment, the right of withdrawal and the statutory warranty. Purchase prices or internal data such as staff numbers are business secrets, not mandatory information." },
      hu: { q: "Miről kell egy webáruháznak a vevőit a szerződéskötés ELŐTT tájékoztatnia? Válaszd ki az összes helyes választ.", o: ["A termék lényeges tulajdonságairól", "Az adókat is tartalmazó árról", "Az elállási jogról", "A saját beszállítójától kapott beszerzési árról", "A szavatosságról", "A raktárban dolgozók számáról"], e: "A szerződéskötés előtt az eladónak tájékoztatnia kell a termék tulajdonságairól, az adókat is tartalmazó árról, a szállításról/fizetésről, az elállási jogról és a szavatosságról. A beszerzési ár vagy a létszám belső üzleti adat, nem kötelező tájékoztatás." },
    },
    {
      type: "multi", level: 1, correct: [0, 2, 3],
      de: { q: "Welche Verhaltensweisen gehören zu den Tipps für sicheres Onlineshopping? Wähle alle zutreffenden.", o: ["Bestellbestätigung und AGB speichern", "Möglichst im Voraus zahlen, damit schneller geliefert wird", "Auf „https://“ und das Schloss-Symbol achten", "Bei Gratisangeboten misstrauisch sein", "Shops außerhalb der EU bevorzugen, weil sie billiger sind"], e: "Belege speichern, auf eine verschlüsselte Verbindung achten und Gratis-Lockangebote hinterfragen schützt vor Problemen. Vorauszahlung erhöht dagegen das Betrugsrisiko, und empfohlen werden geprüfte Shops aus der EU." },
      en: { q: "Which behaviours are among the tips for safe online shopping? Select all that apply.", o: ["Save the order confirmation and terms and conditions", "Pay in advance whenever possible so delivery is faster", "Look for “https://” and the padlock symbol", "Be suspicious of free offers", "Prefer shops outside the EU because they are cheaper"], e: "Saving documents, checking for an encrypted connection and questioning free bait offers protect you. Paying in advance, by contrast, increases the risk of fraud, and certified shops within the EU are recommended." },
      hu: { q: "Mely viselkedésformák tartoznak a biztonságos online vásárlás tippjei közé? Válaszd ki az összes helyes választ.", o: ["A megrendelés-visszaigazolás és az ÁSZF elmentése", "Lehetőleg előre fizetni, hogy gyorsabb legyen a szállítás", "Figyelni a „https://” előtagra és a lakat szimbólumra", "Gyanakvónak lenni az ingyenes ajánlatokkal szemben", "EU-n kívüli webáruházakat választani, mert olcsóbbak"], e: "A bizonylatok mentése, a titkosított kapcsolat ellenőrzése és az ingyenes csalogató ajánlatok megkérdőjelezése véd a problémáktól. Az előre fizetés viszont növeli a csalás kockázatát, és ellenőrzött EU-s webáruházak ajánlottak." },
    },
    {
      type: "match", level: 2,
      de: { q: "Ordne jede Pflicht des Onlinehändlers dem passenden Beispiel zu.", p: [["Informationspflicht", "Impressum mit UID- und Firmenbuchnummer"], ["Bestätigungspflicht", "Button „Jetzt kostenpflichtig bestellen“"], ["Lieferfrist", "Spätestens 30 Tage nach Vertragsabschluss"], ["Rücktrittsrecht", "Belehrung, wie man vom Kauf zurücktritt"]], e: "Das Impressum gehört zur Informationspflicht, der eindeutige Bestellbutton samt Bestellbestätigung zur Bestätigungspflicht. Ohne andere Vereinbarung muss binnen 30 Tagen geliefert werden, und über das Rücktrittsrecht muss belehrt werden." },
      en: { q: "Match each duty of the online seller with the right example.", p: [["Duty to inform", "Legal notice with VAT ID and company register no."], ["Duty to confirm", "Button “Order now with obligation to pay”"], ["Delivery period", "At the latest 30 days after the contract"], ["Right of withdrawal", "Instructions on how to withdraw from the purchase"]], e: "The legal notice (Impressum) is part of the duty to inform; the clear order button plus order confirmation is the duty to confirm. Unless agreed otherwise, delivery must happen within 30 days, and customers must be told about their right of withdrawal." },
      hu: { q: "Párosítsd az online kereskedő kötelezettségeit a megfelelő példával.", p: [["Tájékoztatási kötelezettség", "Impresszum közösségi adószámmal és cégjegyzékszámmal"], ["Visszaigazolási kötelezettség", "„Fizetési kötelezettséggel járó megrendelés” gomb"], ["Szállítási határidő", "Legkésőbb 30 nappal a szerződéskötés után"], ["Elállási jog", "Tájékoztatás arról, hogyan lehet elállni a vételtől"]], e: "Az impresszum a tájékoztatási kötelezettség része, az egyértelmű megrendelés gomb és a visszaigazolás a visszaigazolási kötelezettségé. Eltérő megállapodás hiányában 30 napon belül szállítani kell, és az elállási jogról tájékoztatni kell a vevőt." },
    },
    {
      type: "mc", level: 2, correctIndex: 1,
      de: { q: "Eine Kundin bestellt und bezahlt am 1. März eine große Pralinenbox in Loopys Onlineshop. Am 20. März merkt Loopy, dass sie wegen eines Lieferengpasses erst im Mai liefern kann. Was muss Loopy tun?", o: ["Einfach im Mai liefern – die 30-Tage-Frist gilt nur im B2B-Geschäft", "Die Kundin sofort informieren und das bezahlte Geld zurückzahlen", "Der Kundin eine Stornogebühr verrechnen, falls sie nicht warten will", "Ein anderes Produkt schicken, das die Kundin behalten muss"], e: "Die Lieferfrist beträgt spätestens 30 Tage nach Vertragsabschluss. Kann der Händler sie nicht einhalten, muss er die Kundin sofort informieren und bereits Bezahltes zurückzahlen. Die Frist schützt gerade Konsument:innen; eine Stornogebühr oder ein aufgezwungenes Ersatzprodukt ist unzulässig." },
      en: { q: "On 1 March a customer orders and pays for a large praline box in Loopy's online shop. On 20 March Loopy realises that, due to a supply shortage, she cannot deliver until May. What must Loopy do?", o: ["Simply deliver in May – the 30-day rule only applies to B2B", "Inform the customer immediately and refund the money paid", "Charge the customer a cancellation fee if she won't wait", "Send a different product that the customer has to keep"], e: "Delivery must take place at the latest 30 days after the contract. If the seller cannot manage this, they must inform the customer immediately and refund any payment. The rule protects consumers in particular; a cancellation fee or a forced substitute product is not allowed." },
      hu: { q: "Egy vevő március 1-jén megrendel és kifizet egy nagy bonbonos dobozt Loopy webáruházában. Március 20-án Loopy rájön, hogy ellátási nehézségek miatt csak májusban tud szállítani. Mit kell Loopynak tennie?", o: ["Egyszerűen májusban szállít – a 30 napos határidő csak B2B-ben érvényes", "Azonnal tájékoztatja a vevőt, és visszafizeti a kifizetett összeget", "Lemondási díjat számít fel, ha a vevő nem akar várni", "Másik terméket küld, amelyet a vevőnek meg kell tartania"], e: "A szállítási határidő legkésőbb 30 nap a szerződéskötéstől. Ha az eladó ezt nem tudja tartani, azonnal tájékoztatnia kell a vevőt, és vissza kell fizetnie a már kifizetett összeget. A szabály éppen a fogyasztókat védi; lemondási díj vagy ráerőltetett helyettesítő termék nem megengedett." },
    },
    {
      type: "mc", level: 3, correctIndex: 1,
      de: { q: "Im Onlineshop eines Grazer Modehändlers steht am Ende des Bestellvorgangs nur ein Button mit der Aufschrift „Weiter“. Ein Kunde klickt darauf und erhält eine Rechnung. Wie ist die Rechtslage?", o: ["Der Vertrag gilt, denn jeder Klick im Shop ist eine Bestellung", "Nicht bindend, weil der Button die Zahlungspflicht nicht klar zeigt", "Der Vertrag gilt, der Kunde hat aber 30 statt 14 Tage Rücktrittsrecht", "Der Vertrag gilt erst, wenn der Kunde die Rechnung bezahlt hat"], e: "Laut Bestätigungspflicht muss eindeutig erkennbar sein, dass der Klick eine Zahlungspflicht auslöst (z. B. „zahlungspflichtig bestellen“). Fehlt das, ist der Konsument an die Bestellung nicht gebunden (FAGG). Eine längere Rücktrittsfrist ist dafür nicht die Rechtsfolge." },
      en: { q: "In the online shop of a fashion retailer in Graz, the last step of the checkout only shows a button labelled “Continue”. A customer clicks it and receives an invoice. What is the legal position?", o: ["The contract is valid because every click in the shop is an order", "Not binding, because the button doesn't show the duty to pay", "The contract is valid, but he has 30 instead of 14 days to withdraw", "The contract only becomes valid once the customer pays the invoice"], e: "Under the duty to confirm it must be obvious that the click triggers an obligation to pay (e.g. “order with obligation to pay”). If not, the consumer is not bound by the order (FAGG). A longer withdrawal period is not the legal consequence." },
      hu: { q: "Egy grazi divatkereskedő webáruházában a rendelési folyamat végén csak egy „Tovább” feliratú gomb van. Egy vevő rákattint, és számlát kap. Mi a jogi helyzet?", o: ["A szerződés érvényes, mert minden kattintás a boltban megrendelés", "Nem köti a vevőt, mert a gomb nem jelzi a fizetési kötelezettséget", "A szerződés érvényes, de a vevőnek 14 helyett 30 napja van elállni", "A szerződés csak akkor érvényes, ha a vevő kifizette a számlát"], e: "A visszaigazolási kötelezettség szerint egyértelműnek kell lennie, hogy a kattintás fizetési kötelezettséget von maga után (pl. „fizetési kötelezettséggel járó megrendelés”). Ha ez hiányzik, a fogyasztót nem köti a megrendelés (FAGG). Hosszabb elállási határidő nem jogkövetkezmény." },
    },
    {
      type: "mc", level: 3, correctIndex: 2,
      de: { q: "Die Tischlerei Huber GmbH bestellt für ihre Werkstatt im Onlineshop eines Werkzeughändlers eine Kreissäge. Zehn Tage nach der Lieferung will sie die Säge ohne Angabe von Gründen zurückschicken. Was gilt?", o: ["Sie darf zurücktreten – 14 Tage gelten bei jedem Onlinekauf", "Sie darf zurücktreten, muss aber eine Stornogebühr zahlen", "Kein Rücktrittsrecht, außer es wurde vereinbart", "Sie darf zurücktreten, weil die Lieferfrist 30 Tage beträgt"], e: "Die besonderen Rücktrittsrechte im Fernabsatz (FAGG) schützen Konsument:innen. Kauft ein Unternehmen für seinen Betrieb ein (B2B), gibt es kein gesetzliches Rücktrittsrecht ohne Gründe – eine Rückgabe ist nur möglich, wenn sie vertraglich (z. B. in den AGB) vereinbart ist." },
      en: { q: "Tischlerei Huber GmbH (a joinery) orders a circular saw for its workshop from a tool dealer's online shop. Ten days after delivery it wants to send the saw back without giving reasons. What applies?", o: ["It may withdraw – 14 days apply to every online purchase", "It may withdraw but must pay a cancellation fee", "No right of withdrawal unless it was agreed", "It may withdraw because the delivery period is 30 days"], e: "The special withdrawal rights for distance selling (FAGG) protect consumers. If a company buys for its business (B2B), there is no statutory right to withdraw without reasons – a return is only possible if agreed in the contract (e.g. in the terms and conditions)." },
      hu: { q: "A Huber Asztalosüzem Kft. a műhelye számára egy szerszámkereskedő webáruházában körfűrészt rendel. Tíz nappal a kiszállítás után indoklás nélkül vissza akarja küldeni. Mi érvényes?", o: ["Elállhat – minden online vásárlásnál 14 nap jár", "Elállhat, de lemondási díjat kell fizetnie", "Csak akkor állhat el, ha ezt kikötötték", "Elállhat, mert a szállítási határidő 30 nap"], e: "A távértékesítésre vonatkozó különleges elállási jogok (FAGG) a fogyasztókat védik. Ha egy vállalkozás az üzeme számára vásárol (B2B), nincs indoklás nélküli törvényi elállási jog – visszaküldés csak akkor lehetséges, ha a szerződésben (pl. az ÁSZF-ben) megállapodtak róla." },
    },
    {
      type: "text", level: 2,
      de: { q: "Wie nennt man einen betrügerischen Onlineshop, der nach der Zahlung verschwindet und nie liefert?", a: ["Fake Shop", "Fake-Shop", "Fakeshop", "Fake-Shops", "Fake Shops", "Fake-Onlineshop"], e: "Ein Fake Shop wirkt wie ein echter Onlineshop, kassiert aber nur Vorauszahlungen und liefert nie. Schutz: Impressum und Gütezeichen prüfen, nicht im Voraus zahlen." },
      en: { q: "What do you call a fraudulent online shop that disappears after payment and never delivers?", a: ["fake shop", "fake-shop", "fakeshop", "fake online shop", "scam shop"], e: "A fake shop looks like a real online shop but only collects advance payments and never delivers. Protection: check the legal notice and trust marks, don't pay in advance." },
      hu: { q: "Hogyan nevezzük azt a csaló webáruházat, amely a fizetés után eltűnik, és soha nem szállít?", a: ["kamu webshop", "kamu webáruház", "hamis webshop", "hamis webáruház", "álwebshop", "fake shop"], e: "A kamu webshop valódi webáruháznak tűnik, de csak beszedi az előre fizetett összegeket, és soha nem szállít. Védekezés: ellenőrizd az impresszumot és a minőségi jelzéseket, ne fizess előre." },
    },
  ],

  "ruecktrittsrechte": [
    {
      type: "tf", level: 1, correct: true,
      de: { q: "Der Rücktritt nach dem FAGG ist an keine bestimmte Form gebunden und kann daher auch telefonisch erklärt werden.", e: "Richtig: Für den Rücktritt ist keine Form vorgeschrieben. Schriftlich (E-Mail, Brief, Formular) ist trotzdem besser, weil man den rechtzeitigen Rücktritt dann beweisen kann." },
      en: { q: "Withdrawal under the FAGG does not require any particular form and can therefore also be declared by phone.", e: "True: no form is prescribed for withdrawal. In writing (email, letter, form) is still better, because then you can prove you withdrew in time." },
      hu: { q: "A FAGG szerinti elállás nincs meghatározott formához kötve, ezért telefonon is bejelenthető.", e: "Igaz: az elálláshoz nem írnak elő formát. Írásban (e-mail, levél, nyomtatvány) mégis jobb, mert így bizonyítható, hogy időben elálltunk." },
    },
    {
      type: "tf", level: 2, correct: false,
      de: { q: "Ein Kauf an einem Messestand gilt als Geschäft außerhalb der Geschäftsräume, deshalb besteht ein 14-tägiges Rücktrittsrecht.", e: "Falsch: Ein Messestand gilt als Geschäftsraum. Wer dort kauft, wird nicht „überrumpelt“ wie bei einem Haustürgeschäft oder einer Werbefahrt – das besondere Rücktrittsrecht gilt daher nicht." },
      en: { q: "A purchase at a trade fair stand counts as a contract concluded off business premises, so there is a 14-day right of withdrawal.", e: "False: a trade fair stand counts as business premises. Buyers there are not taken by surprise as with a doorstep sale or a promotional trip – so the special right of withdrawal does not apply." },
      hu: { q: "A vásári standon történő vásárlás üzlethelyiségen kívül kötött ügyletnek számít, ezért 14 napos elállási jog jár.", e: "Hamis: a vásári stand üzlethelyiségnek számít. Az ott vásárlót nem „rohanják le” úgy, mint egy házaló kereskedőnél vagy egy reklámúton – ezért a különleges elállási jog nem érvényes." },
    },
    {
      type: "tf", level: 2, correct: false,
      de: { q: "Tritt eine Kundin von einem Onlinekauf zurück, muss in jedem Fall der Verkäufer die Kosten der Rücksendung tragen.", e: "Falsch: Wurde die Kundin vorher darüber informiert, trägt SIE die Kosten der Rücksendung. Der Verkäufer muss dann den Kaufpreis zurückzahlen." },
      en: { q: "If a customer withdraws from an online purchase, the seller always has to pay the cost of returning the goods.", e: "False: if the customer was informed about this beforehand, SHE bears the return costs. The seller must then refund the purchase price." },
      hu: { q: "Ha egy vevő eláll egy online vásárlástól, a visszaküldés költségét minden esetben az eladónak kell viselnie.", e: "Hamis: ha a vevőt előre tájékoztatták erről, a visszaküldés költségét Ő viseli. Az eladónak ezután vissza kell fizetnie a vételárat." },
    },
    {
      type: "multi", level: 1, correct: [0, 1, 3],
      de: { q: "Was gilt für das besondere Rücktrittsrecht von Konsument:innen im Fernabsatz? Wähle alle zutreffenden Aussagen.", o: ["Man muss keine Gründe angeben", "Es darf keine Stornogebühr verlangt werden", "Es gilt auch für jeden Kauf im Geschäftslokal", "Die Frist beträgt grundsätzlich 14 Kalendertage", "Der Rücktritt ist nur per eingeschriebenem Brief gültig"], e: "Im Fernabsatz und bei Geschäften außerhalb der Geschäftsräume kann man binnen 14 Kalendertagen ohne Gründe und ohne Stornogebühr zurücktreten. Für Käufe im Geschäftslokal gilt das nicht, und eine bestimmte Form ist nicht vorgeschrieben." },
      en: { q: "What applies to consumers' special right of withdrawal in distance selling? Select all that apply.", o: ["No reasons have to be given", "No cancellation fee may be charged", "It also applies to every purchase in a shop", "The period is generally 14 calendar days", "Withdrawal is only valid by registered letter"], e: "For distance contracts and contracts concluded off business premises, consumers can withdraw within 14 calendar days without reasons and without a cancellation fee. This does not apply to purchases in a shop, and no particular form is required." },
      hu: { q: "Mi érvényes a fogyasztók különleges elállási jogára távértékesítésnél? Válaszd ki az összes helyes állítást.", o: ["Nem kell indokot megadni", "Nem kérhető lemondási díj", "Minden üzletben történő vásárlásra is vonatkozik", "A határidő alapvetően 14 naptári nap", "Az elállás csak ajánlott levélben érvényes"], e: "Távértékesítésnél és üzlethelyiségen kívül kötött ügyleteknél 14 naptári napon belül indoklás és lemondási díj nélkül lehet elállni. Üzletben történő vásárlásra ez nem vonatkozik, és meghatározott forma sem kötelező." },
    },
    {
      type: "multi", level: 3, correct: [0, 1, 3, 5],
      de: { q: "Bei welchen Geschäften gibt es trotz Fernabsatz bzw. Auswärtsgeschäft KEIN Rücktrittsrecht? Wähle alle zutreffenden.", o: ["Online bestellte Pizza, die nach Hause geliefert wird", "Maßgeschneidertes Hochzeitskleid", "Online bestellte Jacke in Standardgröße", "Konzertkarte für einen bestimmten Termin", "Staubsauger, gekauft auf einer Werbefahrt", "Software-DVD, deren Siegel geöffnet wurde"], e: "Ausgenommen sind Lebensmittel-Hauszustellungen, Sonderanfertigungen, entsiegelte Software/CDs/DVDs, dringende Reparaturen und Freizeitdienstleistungen mit fixem Termin. Die Standard-Jacke und der Staubsauger von der Werbefahrt fallen dagegen voll unter das Rücktrittsrecht." },
      en: { q: "For which transactions is there NO right of withdrawal despite distance selling or an off-premises contract? Select all that apply.", o: ["Pizza ordered online and delivered to your home", "Tailor-made wedding dress", "Jacket in a standard size ordered online", "Concert ticket for a specific date", "Vacuum cleaner bought on a promotional trip", "Software DVD whose seal has been opened"], e: "Exceptions are home deliveries of food, custom-made goods, unsealed software/CDs/DVDs, urgent repairs and leisure services for a fixed date. The standard jacket and the vacuum cleaner from the promotional trip, by contrast, are fully covered by the right of withdrawal." },
      hu: { q: "Mely ügyleteknél NINCS elállási jog annak ellenére, hogy távértékesítésről vagy üzlethelyiségen kívül kötött szerződésről van szó? Válaszd ki az összes helyeset.", o: ["Online rendelt, házhoz szállított pizza", "Méretre szabott esküvői ruha", "Online rendelt, normál méretű dzseki", "Koncertjegy egy meghatározott időpontra", "Reklámúton vásárolt porszívó", "Szoftver-DVD, amelynek a zárócímkéjét feltörték"], e: "Kivételt jelent az élelmiszerek házhoz szállítása, az egyedi gyártás, a felbontott szoftver/CD/DVD, a sürgős javítás és az időponthoz kötött szabadidős szolgáltatás. A normál méretű dzsekire és a reklámúton vett porszívóra viszont teljes mértékben vonatkozik az elállási jog." },
    },
    {
      type: "match", level: 2,
      de: { q: "Ordne jeden Fall dem passenden Weg der Vertragsauflösung zu.", p: [["Händlerin nimmt ein Kleid aus Kulanz zurück", "Abänderung (einvernehmliche Auflösung)"], ["Reise wegen Krankheit gegen Gebühr abgesagt", "Stornierung"], ["Verkäufer verschwieg bewusst einen Unfallschaden", "Rücktritt wegen arglistiger Täuschung"], ["Vertreter verkauft an der Haustür ein Abo", "Besonderes Rücktrittsrecht (14 Tage)"]], e: "Sind beide einverstanden, ist es eine Abänderung; gegen Stornogebühr eine Stornierung. Arglistige Täuschung berechtigt allgemein zum Rücktritt, und beim Haustürgeschäft schützt das besondere Rücktrittsrecht für Konsument:innen." },
      en: { q: "Match each case with the right way of ending the contract.", p: [["Shop owner takes back a dress as a goodwill gesture", "Modification (termination by mutual consent)"], ["Trip cancelled due to illness, for a fee", "Cancellation"], ["Seller deliberately concealed accident damage", "Withdrawal due to fraudulent misrepresentation"], ["Sales rep sells a subscription at the door", "Special right of withdrawal (14 days)"]], e: "If both agree, it is a modification; for a cancellation fee it is a cancellation. Fraudulent misrepresentation generally entitles the buyer to withdraw, and for doorstep sales consumers are protected by the special right of withdrawal." },
      hu: { q: "Párosítsd az eseteket a szerződés felbontásának megfelelő módjával.", p: [["Az eladó méltányosságból visszaveszi a ruhát", "Módosítás (közös megegyezéses felbontás)"], ["Betegség miatt díj ellenében lemondott utazás", "Lemondás (sztornó)"], ["Az eladó szándékosan elhallgatta a baleseti kárt", "Elállás csalárd megtévesztés miatt"], ["Ügynök az ajtóban előfizetést ad el", "Különleges elállási jog (14 nap)"]], e: "Ha mindkét fél egyetért, módosításról van szó; lemondási díj ellenében lemondásról. A csalárd megtévesztés általánosan elállásra jogosít, házaló értékesítésnél pedig a fogyasztók különleges elállási joga véd." },
    },
    {
      type: "mc", level: 2, correctIndex: 0,
      de: { q: "Herr Berger kauft auf einer Werbefahrt eine Heizdecke um 290 €. Er wird ordnungsgemäß über sein Rücktrittsrecht informiert und nimmt die Decke gleich mit. Neun Tage später bereut er den Kauf. Was gilt?", o: ["Rücktritt möglich – ohne Gründe und ohne Gebühr", "Kein Rücktritt, weil er die Ware sofort mitgenommen hat", "Rücktritt möglich, aber nur gegen eine Stornogebühr", "Kein Rücktritt, denn das gilt nur für Onlinekäufe"], e: "Eine Werbefahrt ist ein Geschäft außerhalb der Geschäftsräume. Wurde die Ware sofort übergeben, läuft die 14-tägige Frist ab Vertragsabschluss – nach neun Tagen ist sie noch offen. Der Rücktritt ist ohne Gründe und ohne Stornogebühr möglich." },
      en: { q: "Mr Berger buys an electric blanket for €290 on a promotional trip. He is properly informed about his right of withdrawal and takes the blanket with him straight away. Nine days later he regrets the purchase. What applies?", o: ["Withdrawal possible – without reasons and without a fee", "No withdrawal, because he took the goods with him at once", "Withdrawal possible, but only for a cancellation fee", "No withdrawal, because that only applies to online purchases"], e: "A promotional trip is a contract concluded off business premises. If the goods were handed over immediately, the 14-day period runs from the conclusion of the contract – after nine days it is still open. He can withdraw without reasons and without a cancellation fee." },
      hu: { q: "Berger úr egy reklámúton 290 €-ért elektromos melegítőtakarót vesz. Szabályszerűen tájékoztatják az elállási jogáról, és a takarót azonnal magával viszi. Kilenc nappal később megbánja a vásárlást. Mi érvényes?", o: ["Elállhat – indoklás és díj nélkül", "Nem állhat el, mert az árut azonnal magával vitte", "Elállhat, de csak lemondási díj ellenében", "Nem állhat el, mert ez csak online vásárlásra vonatkozik"], e: "A reklámút üzlethelyiségen kívül kötött ügyletnek számít. Ha az árut azonnal átadták, a 14 napos határidő a szerződéskötéstől fut – kilenc nap után még nem járt le. Az elállás indoklás és lemondási díj nélkül lehetséges." },
    },
    {
      type: "mc", level: 3, correctIndex: 1,
      de: { q: "Eine Kundin bestellt online Sneaker, die am 2. März geliefert werden. Über ihr Rücktrittsrecht wurde sie nicht informiert. Am 10. Juni schickt der Shop die Belehrung per E-Mail nach. Bis wann kann sie zurücktreten?", o: ["Gar nicht mehr – die Frist endete schon am 16. März", "Bis 24. Juni – 14 Tage ab Erhalt der Belehrung", "Bis 16. März des Folgejahres – 1 Jahr plus 14 Tage", "Bis 10. Juli – 30 Tage ab Erhalt der E-Mail"], e: "Ohne Belehrung verlängert sich die Frist auf 1 Jahr + 14 Tage. Holt der Händler die Information innerhalb dieses Jahres nach, endet die Frist 14 Tage nach Erhalt der Belehrung (FAGG) – hier also am 24. Juni. Die verlängerte Frist gilt nur, solange nicht nachträglich informiert wird." },
      en: { q: "A customer orders sneakers online, which are delivered on 2 March. She was not informed about her right of withdrawal. On 10 June the shop sends the information by email. Until when can she withdraw?", o: ["Not at all – the period already ended on 16 March", "Until 24 June – 14 days after receiving the information", "Until 16 March of the following year – 1 year plus 14 days", "Until 10 July – 30 days after receiving the email"], e: "Without information, the period is extended to 1 year + 14 days. If the seller provides the information within that year, the period ends 14 days after it is received (FAGG) – here on 24 June. The extended period only applies as long as no information is provided later." },
      hu: { q: "Egy vevő online sportcipőt rendel, amelyet március 2-án szállítanak ki. Az elállási jogáról nem tájékoztatták. A webáruház június 10-én e-mailben pótolja a tájékoztatást. Meddig állhat el?", o: ["Már egyáltalán nem – a határidő március 16-án lejárt", "Június 24-ig – 14 nap a tájékoztatás kézhezvételétől", "A következő év március 16-ig – vagyis 1 év plusz 14 nap", "Július 10-ig – az e-mail kézhezvételétől számított 30 napig"], e: "Tájékoztatás hiányában a határidő 1 év + 14 napra hosszabbodik. Ha az eladó ezen az éven belül pótolja a tájékoztatást, a határidő a kézhezvételtől számított 14 nap múlva jár le (FAGG) – itt június 24-én. A meghosszabbított határidő csak addig él, amíg utólag nem tájékoztatnak." },
    },
    {
      type: "mc", level: 3, correctIndex: 2,
      de: { q: "Lena bestellt online ein Abendkleid, trägt es auf einer Hochzeit und tritt danach innerhalb der 14 Tage vom Vertrag zurück. Was gilt?", o: ["Rücktritt ausgeschlossen, weil das Kleid schon getragen wurde", "Rücktritt möglich, der volle Preis muss erstattet werden", "Rücktritt möglich, aber mit Entschädigung für die Benützung", "Rücktritt möglich, Lena bekommt aber nur einen Gutschein"], e: "Das Rücktrittsrecht bleibt bestehen, doch wurde die Ware benutzt oder verbraucht, darf der Verkäufer eine Entschädigung (für den Wertverlust) verlangen. Ein Gutschein statt Geld ist beim gesetzlichen Rücktritt nicht zulässig – der Verkäufer muss das Geld zurückzahlen." },
      en: { q: "Lena orders an evening dress online, wears it at a wedding and then withdraws from the contract within the 14 days. What applies?", o: ["Withdrawal excluded because the dress has already been worn", "Withdrawal possible, the full price must be refunded", "Withdrawal possible, the seller may claim compensation", "Withdrawal possible, but Lena only gets a voucher"], e: "The right of withdrawal remains, but if the goods were used or consumed, the seller may claim compensation (for the loss in value). A voucher instead of money is not allowed for a statutory withdrawal – the seller must refund the money." },
      hu: { q: "Léna online rendel egy estélyi ruhát, felveszi egy esküvőn, majd a 14 napon belül eláll a szerződéstől. Mi érvényes?", o: ["Az elállás kizárt, mert a ruhát használták", "Elállhat, és a teljes árat vissza kell téríteni", "Elállhat, de az eladó kártérítést kérhet", "Elállhat, de Léna csak utalványt kap"], e: "Az elállási jog megmarad, de ha az árut használták vagy elfogyasztották, az eladó kártérítést (az értékcsökkenésért) követelhet. Törvényes elállásnál utalvány a pénz helyett nem megengedett – az eladónak vissza kell fizetnie a pénzt." },
    },
    {
      type: "number", level: 1, value: 26, tol: 0,
      de: { q: "Eine Kundin bestellt in einem Onlineshop eine Jacke und wurde korrekt über ihr Rücktrittsrecht informiert. Die Jacke wird am 12. Oktober geliefert. Bis zu welchem Tag im Oktober kann sie zurücktreten? (Gib nur die Tageszahl an.)", e: "Wird Ware geliefert, läuft die Frist 14 Kalendertage ab Lieferung: 12 + 14 = 26. Rücktritt ist also bis 26. Oktober möglich (wie im Beispiel: Lieferung 7. August → bis 21. August)." },
      en: { q: "A customer orders a jacket from an online shop and was correctly informed about her right of withdrawal. The jacket is delivered on 12 October. Until which day in October can she withdraw? (Enter only the day number.)", e: "If goods are delivered, the period is 14 calendar days from delivery: 12 + 14 = 26. So withdrawal is possible until 26 October (as in the example: delivered 7 August → until 21 August)." },
      hu: { q: "Egy vevő dzsekit rendel egy webáruházból, és szabályszerűen tájékoztatták az elállási jogáról. A dzsekit október 12-én szállítják ki. Október hányadikáig állhat el? (Csak a nap számát add meg.)", e: "Kiszállított árunál a határidő a kiszállítástól számított 14 naptári nap: 12 + 14 = 26. Az elállás tehát október 26-ig lehetséges (mint a példában: kiszállítás augusztus 7. → augusztus 21-ig)." },
    },
  ],

  "bestandteile-kaufvertrag": [
    {
      type: "tf", level: 1, correct: false,
      de: { q: "Ein Gebrauchtwagen ist eine vertretbare (fungible) Ware.", e: "Falsch: Ein Gebrauchtwagen ist einzigartig (Kilometerstand, Zustand, Schäden) und muss genau besichtigt werden – er ist nicht vertretbar. Vertretbar sind gleichwertig ersetzbare Waren wie ein neues Handy oder ein A4-Schulheft." },
      en: { q: "A used car is a fungible (replaceable) good.", e: "False: a used car is unique (mileage, condition, damage) and must be inspected carefully – it is not fungible. Fungible goods can be replaced by equivalent ones, like a new mobile phone or an A4 exercise book." },
      hu: { q: "A használt autó helyettesíthető (fungibilis) áru.", e: "Hamis: a használt autó egyedi (futásteljesítmény, állapot, sérülések), ezért pontosan meg kell tekinteni – nem helyettesíthető. Helyettesíthető az egyenértékűen pótolható áru, például egy új mobiltelefon vagy egy A4-es füzet." },
    },
    {
      type: "tf", level: 2, correct: true,
      de: { q: "Ist im Kaufvertrag kein Liefertermin vereinbart, muss der Verkäufer sofort liefern.", e: "Richtig: Ohne Vereinbarung gilt das Promptgeschäft – Lieferung sofort. Ein Fixgeschäft (genauer Termin) oder Termingeschäft (ungefährer Termin) muss ausdrücklich vereinbart werden." },
      en: { q: "If no delivery date is agreed in the contract of sale, the seller must deliver immediately.", e: "True: without an agreement, a spot transaction (Promptgeschäft) applies – immediate delivery. A fixed-date or forward transaction must be agreed explicitly." },
      hu: { q: "Ha az adásvételi szerződésben nem állapodtak meg a szállítási időpontról, az eladónak azonnal szállítania kell.", e: "Igaz: megállapodás hiányában azonnali ügylet érvényes – azonnali szállítás. A fix határidős ügyletet (pontos időpont) vagy a határidős ügyletet (hozzávetőleges időpont) kifejezetten ki kell kötni." },
    },
    {
      type: "tf", level: 3, correct: false,
      de: { q: "AGB werden auch dann Vertragsinhalt, wenn die Käuferin sie erst nach Vertragsabschluss auf der Rückseite der Rechnung erhält.", e: "Falsch: AGB gelten nur, wenn die Käuferin sie VOR Vertragsabschluss kennen konnte. Auf der Rechnung kommen sie zu spät – der Vertrag ist da schon geschlossen." },
      en: { q: "Terms and conditions become part of the contract even if the buyer only receives them on the back of the invoice after the contract was concluded.", e: "False: terms and conditions only apply if the buyer could know them BEFORE the contract was concluded. On the invoice they come too late – the contract has already been made." },
      hu: { q: "Az ÁSZF akkor is a szerződés részévé válik, ha a vevő csak a szerződéskötés után, a számla hátoldalán kapja meg.", e: "Hamis: az ÁSZF csak akkor érvényes, ha a vevő a szerződéskötés ELŐTT megismerhette. A számlán már túl késő – a szerződés addigra létrejött." },
    },
    {
      type: "multi", level: 2, correct: [0, 1, 3],
      de: { q: "Welche Vereinbarungen führen zu einem freibleibenden (nicht festen) Preis? Wähle alle zutreffenden.", o: ["Wertsicherungsklausel (Bindung an den Verbraucherpreisindex)", "Heizöl zum Tagespreis an der Börse", "Fixpreis von 12 € pro Stück", "Kostenschwankungsklausel beim Hausbau", "Mengenrabatt von 5 % ab 100 Stück"], e: "Freibleibend ist ein Preis, der sich nach Vertragsabschluss noch ändern kann: Markt-/Börsenpreis, Wertsicherungsklausel, Basiskauf, Kostenschwankungsklausel. Ein Fixpreis ist fest, und ein Mengenrabatt ist ein Preisnachlass, keine Preisanpassung." },
      en: { q: "Which agreements lead to a variable (not fixed) price? Select all that apply.", o: ["Value-protection clause (linked to the consumer price index)", "Heating oil at the daily exchange price", "Fixed price of €12 per piece", "Cost-fluctuation clause when building a house", "5% quantity discount from 100 pieces"], e: "A price is variable if it can still change after the contract: market/exchange price, value-protection clause, basis purchase, cost-fluctuation clause. A fixed price is fixed, and a quantity discount is a price reduction, not a price adjustment." },
      hu: { q: "Mely megállapodások eredményeznek változó (nem rögzített) árat? Válaszd ki az összes helyeset.", o: ["Értékállandósági záradék (a fogyasztói árindexhez kötve)", "Fűtőolaj a tőzsdei napi áron", "Darabonként 12 € fix ár", "Költségingadozási záradék házépítésnél", "5% mennyiségi engedmény 100 darabtól"], e: "Változó az az ár, amely a szerződéskötés után még változhat: piaci/tőzsdei ár, értékállandósági záradék, bázisvétel, költségingadozási záradék. A fix ár rögzített, a mennyiségi engedmény pedig árengedmény, nem árkiigazítás." },
    },
    {
      type: "multi", level: 1, correct: [0, 2, 4],
      de: { q: "Welche Rabattarten werden wegen großer Abnahmemengen gewährt? Wähle alle zutreffenden.", o: ["Mengenrabatt", "Treuerabatt", "Umsatzbonus am Jahresende", "Einführungsrabatt", "Naturalrabatt"], e: "Mengenrabatt, Schlussrabatt, Naturalrabatt (Drauf-/Dreingabe) und Umsatzbonus belohnen große Mengen. Der Treuerabatt belohnt Stammkund:innen, der Einführungsrabatt ein besonderes Ereignis (neues Produkt)." },
      en: { q: "Which types of discount are granted because of large purchase quantities? Select all that apply.", o: ["Quantity discount", "Loyalty discount", "Year-end turnover bonus", "Introductory discount", "Discount in kind"], e: "Quantity discount, final discount, discount in kind (extra goods) and turnover bonus reward large quantities. A loyalty discount rewards regular customers, an introductory discount a special event (new product)." },
      hu: { q: "Mely engedményfajtákat adják nagy vásárolt mennyiség miatt? Válaszd ki az összes helyeset.", o: ["Mennyiségi engedmény", "Hűségkedvezmény", "Év végi forgalmi bónusz", "Bevezető engedmény", "Természetbeni engedmény"], e: "A mennyiségi engedmény, a záró engedmény, a természetbeni engedmény (ráadás) és a forgalmi bónusz a nagy mennyiséget jutalmazza. A hűségkedvezmény a törzsvásárlókat, a bevezető engedmény egy különleges eseményt (új termék) jutalmaz." },
    },
    {
      type: "order", level: 2,
      de: { q: "Bringe die Zeilen der Bezugskalkulation in die richtige Reihenfolge.", o: ["Listeneinkaufspreis", "− Lieferantenrabatt", "= Zieleinkaufspreis", "− Lieferantenskonto", "= Kassaeinkaufspreis", "+ Bezugskosten", "= Einstandspreis"], e: "Zuerst wird vom Listenpreis der Rabatt abgezogen (Zieleinkaufspreis), dann das Skonto vom bereits rabattierten Betrag (Kassaeinkaufspreis). Erst zum Schluss kommen die Bezugskosten dazu – das Ergebnis ist der Einstandspreis." },
      en: { q: "Put the lines of the purchase price calculation in the correct order.", o: ["List purchase price", "− Supplier discount", "= Target purchase price", "− Supplier cash discount", "= Cash purchase price", "+ Acquisition costs", "= Landed cost price"], e: "First the discount is deducted from the list price (target purchase price), then the cash discount from the already discounted amount (cash purchase price). Only at the end are acquisition costs added – the result is the landed cost price." },
      hu: { q: "Állítsd helyes sorrendbe a beszerzési kalkuláció sorait.", o: ["Listás beszerzési ár", "− szállítói engedmény", "= célbeszerzési ár", "− szállítói skontó", "= készpénzes beszerzési ár", "+ beszerzési költségek", "= bekerülési ár"], e: "Először a listaárból vonjuk le az engedményt (célbeszerzési ár), majd a skontót a már csökkentett összegből (készpénzes beszerzési ár). A beszerzési költségeket csak a végén adjuk hozzá – az eredmény a bekerülési ár." },
    },
    {
      type: "match", level: 1,
      de: { q: "Ordne jede Kaufart der passenden Bedeutung zu.", p: [["Kauf nach Probe", "Ware muss genau wie die Probe sein"], ["Kauf auf Probe", "Rückgabe innerhalb einer Frist möglich"], ["Kauf zur Probe", "Kleine Menge testen, keine Rückgabe"], ["Spezifikationskauf", "Käufer legt Größe/Farbe erst später fest"]], e: "Nach Probe = Probe bestimmt die Qualität (Fliesenmuster); auf Probe = Testen mit Rückgaberecht (Matratze); zur Probe = kleine Testmenge ohne Rückgabe (Wandfarbe). Beim Spezifikationskauf bestimmt der Käufer Details nachträglich." },
      en: { q: "Match each type of purchase with its meaning.", p: [["Sale by sample", "Goods must be exactly like the sample"], ["Sale on approval", "Return possible within a period"], ["Trial purchase", "Test a small quantity, no return"], ["Purchase by specification", "Buyer sets size/colour later"]], e: "By sample = the sample sets the quality (tile sample); on approval = testing with a right to return (mattress); trial purchase = small test quantity without return (wall paint). In a purchase by specification the buyer decides details later." },
      hu: { q: "Párosítsd a vételfajtákat a jelentésükkel.", p: [["Minta szerinti vétel", "Az árunak pontosan olyannak kell lennie, mint a minta"], ["Próbára vétel", "Határidőn belül visszaadható"], ["Kipróbálásra vétel", "Kis mennyiség kipróbálása, nincs visszaadás"], ["Specifikációs vétel", "A méretet/színt a vevő később határozza meg"]], e: "Minta szerinti = a minta határozza meg a minőséget (csempeminta); próbára = kipróbálás visszaadási joggal (matrac); kipróbálásra = kis tesztmennyiség visszaadás nélkül (falfesték). Specifikációs vételnél a vevő utólag határozza meg a részleteket." },
    },
    {
      type: "mc", level: 2, correctIndex: 1,
      de: { q: "Loopy bestellt 100 kg Zucker. Der Großhändler liefert 100 kg, stellt aber nur 95 kg in Rechnung. Wie nennt man diesen Naturalrabatt?", o: ["Draufgabe", "Dreingabe", "Skonto", "Kauf in Bausch und Bogen"], e: "Bei der Dreingabe wird weniger verrechnet als geliefert (100 kg geliefert, 95 kg bezahlt). Bei der Draufgabe wird mehr geliefert als bezahlt (z. B. 100 kg bezahlt, 105 kg geliefert). Skonto ist ein Abzug für schnelles Zahlen." },
      en: { q: "Loopy orders 100 kg of sugar. The wholesaler delivers 100 kg but only invoices 95 kg. What is this discount in kind called?", o: ["Draufgabe (extra goods delivered)", "Dreingabe (less invoiced)", "Cash discount", "Purchase in bulk (Bausch und Bogen)"], e: "With a Dreingabe less is invoiced than delivered (100 kg delivered, 95 kg paid). With a Draufgabe more is delivered than paid (e.g. 100 kg paid, 105 kg delivered). A cash discount is a deduction for fast payment." },
      hu: { q: "Loopy 100 kg cukrot rendel. A nagykereskedő 100 kg-ot szállít, de csak 95 kg-ot számláz ki. Hogyan nevezzük ezt a természetbeni engedményt?", o: ["Ráadás (Draufgabe)", "Kedvezményes mennyiség (Dreingabe)", "Skontó (készpénzfizetési engedmény)", "Egy tételben történő vétel"], e: "Kedvezményes mennyiség (Dreingabe) esetén kevesebbet számláznak, mint amennyit szállítanak (100 kg szállítva, 95 kg kifizetve). Ráadásnál (Draufgabe) többet szállítanak, mint amennyit kifizettek (pl. 100 kg kifizetve, 105 kg szállítva). A skontó a gyors fizetésért járó levonás." },
    },
    {
      type: "mc", level: 3, correctIndex: 1,
      de: { q: "Ein Linzer Lieferant verkauft Loopy (Graz) Maschinenteile „frachtfrei Bahnhof Graz“. Auf der Bahnfahrt zwischen Linz und Graz wird die Ware beschädigt. Wer trägt das Risiko?", o: ["Der Lieferant, weil er die Frachtkosten bis Graz bezahlt", "Loopy, weil das Risiko beim ersten Frachtführer übergeht", "Beide je zur Hälfte, weil es eine Zweipunktklausel ist", "Der Lieferant, weil Loopy die Ware noch nicht hat"], e: "„Frachtfrei Bahnhof …“ ist eine Zweipunktklausel: Die Kosten trägt der Verkäufer bis Bahnhof Graz, das Risiko geht aber schon mit Übergabe an den ersten Frachtführer (in Linz) auf die Käuferin über. Wer die Fracht zahlt, trägt hier also nicht automatisch das Risiko." },
      en: { q: "A supplier in Linz sells machine parts to Loopy (Graz) “carriage paid to Graz station”. During the rail journey between Linz and Graz the goods are damaged. Who bears the risk?", o: ["The supplier, because he pays freight to Graz", "Loopy, because the risk passes at the first carrier", "Both half each, because it is a two-point clause", "The supplier, because Loopy doesn't have the goods yet"], e: "“Carriage paid to … station” is a two-point clause: the seller bears the costs up to Graz station, but the risk passes to the buyer as soon as the goods are handed to the first carrier (in Linz). Paying the freight therefore does not automatically mean bearing the risk." },
      hu: { q: "Egy linzi beszállító gépalkatrészeket ad el Loopynak (Graz) „fuvarköltség fizetve grazi állomásig” feltétellel. A Linz és Graz közötti vasúti úton az áru megsérül. Ki viseli a kockázatot?", o: ["A beszállító, mert ő fizeti a fuvart Grazig", "Loopy, mert a kockázat az első fuvarozónál átszáll", "Fele-fele arányban, mert kétpontos záradékról van szó", "A beszállító, mert Loopynál még nincs ott az áru"], e: "A „fuvarköltség fizetve … állomásig” kétpontos záradék: a költséget az eladó viseli a grazi állomásig, a kockázat viszont már az első fuvarozónak (Linzben) történő átadáskor átszáll a vevőre. Aki a fuvart fizeti, itt tehát nem automatikusan viseli a kockázatot is." },
    },
    {
      type: "mc", level: 3, correctIndex: 3,
      de: { q: "Loopy verschickt eine Pralinenbox an eine Privatkundin in Salzburg. Über den Erfüllungsort wurde nichts vereinbart. Das Paket geht bei der Post verloren. Wer trägt das Risiko?", o: ["Die Kundin, weil die Ware dem Frachtführer übergeben wurde", "Die Post allein, Loopy und die Kundin sind nicht betroffen", "Die Kundin, weil sie die Lieferung bestellt hat", "Loopy, weil bei B2C erst die Übergabe an die Kundin zählt"], e: "Ohne Vereinbarung ist der Erfüllungsort bei B2C die Übergabe an die Käuferin – bis dahin trägt der Verkäufer das Risiko, Loopy muss also nochmals liefern. Die Übergabe an den Frachtführer zählt nur im B2B-Geschäft." },
      en: { q: "Loopy sends a praline box to a private customer in Salzburg. Nothing was agreed about the place of performance. The parcel is lost by the post. Who bears the risk?", o: ["The customer, because the goods were handed to the carrier", "The post alone; Loopy and the customer are not affected", "The customer, because she ordered the delivery", "Loopy, because in B2C only handover to the customer counts"], e: "Without an agreement, the place of performance in B2C is the handover to the buyer – until then the seller bears the risk, so Loopy has to deliver again. Handover to the carrier only counts in B2B." },
      hu: { q: "Loopy egy bonbonos dobozt küld egy salzburgi magánvásárlónak. A teljesítési helyről nem állapodtak meg. A csomag elvész a postán. Ki viseli a kockázatot?", o: ["A vevő, mert az árut átadták a fuvarozónak", "Egyedül a posta, Loopyt és a vevőt ez nem érinti", "A vevő, mert ő rendelte meg a kiszállítást", "Loopy, mert B2C-ben a vevőnek való átadás számít"], e: "Megállapodás hiányában B2C-ben a teljesítési hely a vevőnek történő átadás – addig az eladó viseli a kockázatot, Loopynak tehát újra kell szállítania. A fuvarozónak történő átadás csak B2B-ben számít." },
    },
    {
      type: "number", level: 2, value: 25.71, tol: 0.01, unit: { de: "%", en: "%", hu: "%" },
      de: { q: "Eine Rechnung lautet: „Zahlbar binnen 10 Tagen mit 2,5 % Skonto oder 45 Tage netto.“ Wie hoch ist die Jahresverzinsung des Skontos? (Auf 2 Dezimalstellen runden)", e: "Skonto % / (Zahlungsziel − Kassafrist) · 360 = 2,5 / (45 − 10) · 360 = 2,5 / 35 · 360 = 25,71 % p. a. Das ist viel mehr als die Zinsen eines Bankkredits – Skonto ausnützen lohnt sich." },
      en: { q: "An invoice states: “Payable within 10 days less 2.5% cash discount or 45 days net.” What is the annual interest rate of the cash discount? (Round to 2 decimal places)", e: "Discount % / (payment term − discount period) · 360 = 2.5 / (45 − 10) · 360 = 2.5 / 35 · 360 = 25.71% p.a. That is far more than the interest on a bank loan – taking the discount pays off." },
      hu: { q: "A számlán ez áll: „Fizetendő 10 napon belül 2,5% skontóval vagy 45 nap nettó.” Mekkora a skontó éves kamatlába? (2 tizedesjegyre kerekítve)", e: "Skontó % / (fizetési határidő − skontóhatáridő) · 360 = 2,5 / (45 − 10) · 360 = 2,5 / 35 · 360 = évi 25,71%. Ez jóval több egy bankhitel kamatánál – megéri kihasználni a skontót." },
    },
  ],

  "schriftverkehr-kaufvertrag": [
    {
      type: "tf", level: 1, correct: true,
      de: { q: "Der Lieferschein listet die gelieferten Produkte ohne Preise auf.", e: "Richtig: Der Lieferschein zeigt nur Produkte und Mengen, damit die Übernahme geprüft werden kann. Die Preise stehen erst auf der Rechnung." },
      en: { q: "The delivery note lists the delivered products without prices.", e: "True: the delivery note only shows products and quantities so that the delivery can be checked. The prices only appear on the invoice." },
      hu: { q: "A szállítólevél árak nélkül sorolja fel a leszállított termékeket.", e: "Igaz: a szállítólevél csak a termékeket és a mennyiségeket mutatja, hogy az átvételt ellenőrizni lehessen. Az árak csak a számlán szerepelnek." },
    },
    {
      type: "tf", level: 1, correct: true,
      de: { q: "Mit ihrer Unterschrift auf dem Gegenschein bestätigt die Käuferin die Übernahme der Ware; der Gegenschein geht an den Verkäufer zurück.", e: "Richtig: Der Gegenschein ist eine Kopie des Lieferscheins. Die Unterschrift beweist dem Verkäufer, dass geliefert wurde – der Lieferschein selbst bleibt bei der Käuferin." },
      en: { q: "By signing the counterfoil (Gegenschein), the buyer confirms receipt of the goods; the counterfoil goes back to the seller.", e: "True: the counterfoil is a copy of the delivery note. The signature proves to the seller that delivery took place – the delivery note itself stays with the buyer." },
      hu: { q: "Az ellenlevél aláírásával a vevő igazolja az áru átvételét; az ellenlevél visszakerül az eladóhoz.", e: "Igaz: az ellenlevél a szállítólevél másolata. Az aláírás bizonyítja az eladónak, hogy a szállítás megtörtént – maga a szállítólevél a vevőnél marad." },
    },
    {
      type: "tf", level: 2, correct: false,
      de: { q: "Bestellt ein Kunde aufgrund eines Werbekatalogs, ist der Kaufvertrag schon mit dem Absenden der Bestellung abgeschlossen.", e: "Falsch: Ein Katalog ist eine unverbindliche Anpreisung. Die Bestellung ist dann erst das Angebot des Kunden – der Vertrag kommt erst mit der Auftragsbestätigung zustande (Auftragsbestätigung ALS Abschluss)." },
      en: { q: "If a customer orders on the basis of an advertising catalogue, the contract of sale is already concluded when the order is sent.", e: "False: a catalogue is a non-binding advertisement. The order is then only the customer's offer – the contract only comes about with the order confirmation (confirmation AS conclusion)." },
      hu: { q: "Ha egy vevő egy reklámkatalógus alapján rendel, az adásvételi szerződés már a megrendelés elküldésével létrejön.", e: "Hamis: a katalógus nem kötelező érvényű reklám. A megrendelés ilyenkor csak a vevő ajánlata – a szerződés csak a megrendelés-visszaigazolással jön létre (visszaigazolás MINT megkötés)." },
    },
    {
      type: "multi", level: 2, correct: [0, 1, 3],
      de: { q: "Welche UNTERNEHMENSEXTERNEN Quellen kann ein Käufer nutzen, um neue Lieferanten zu finden? Wähle alle zutreffenden.", o: ["Fachmessen", "Lieferantensuchmaschinen wie wlw.at", "Die eigene Bezugsquellendatei", "Wirtschaftskammer (wko.at)", "Der eigene Kontoauszug"], e: "Messen, Lieferantensuchmaschinen, die WKO, Kataloge/Werbemails und Geschäftsfreunde sind externe Quellen. Die Bezugsquellendatei ist eine interne Quelle (Infos über bisherige Lieferanten), und ein Kontoauszug hilft bei der Lieferantensuche nicht." },
      en: { q: "Which EXTERNAL sources can a buyer use to find new suppliers? Select all that apply.", o: ["Trade fairs", "Supplier search engines such as wlw.at", "The company's own supplier file", "Chamber of Commerce (wko.at)", "The company's own bank statement"], e: "Trade fairs, supplier search engines, the Chamber of Commerce (WKO), catalogues/advertising emails and business contacts are external sources. The supplier file is an internal source (information on previous suppliers), and a bank statement does not help to find suppliers." },
      hu: { q: "Mely VÁLLALATON KÍVÜLI forrásokat használhat a vevő új beszállítók felkutatására? Válaszd ki az összes helyeset.", o: ["Szakvásárok", "Beszállítókereső oldalak, pl. wlw.at", "A saját beszerzési forrás-nyilvántartás", "Gazdasági Kamara (wko.at)", "A saját bankszámlakivonat"], e: "A vásárok, a beszállítókereső oldalak, a Gazdasági Kamara (WKO), a katalógusok/reklám e-mailek és az üzleti partnerek külső források. A beszerzési forrás-nyilvántartás belső forrás (adatok a korábbi beszállítókról), a bankszámlakivonat pedig nem segít a beszállítókeresésben." },
    },
    {
      type: "multi", level: 3, correct: [0, 1, 2, 4],
      de: { q: "Welche Angaben muss eine Kleinbetragsrechnung (bis 400 € brutto) enthalten? Wähle alle zutreffenden.", o: ["Name und Anschrift des Verkäufers", "Ausstellungsdatum", "Gesamtbetrag inklusive USt", "UID-Nummer des Käufers", "Steuersatz", "Name und Anschrift des Käufers"], e: "Bei der Kleinbetragsrechnung reichen: Verkäufer, Datum, Menge/Bezeichnung, Gesamtbetrag inkl. USt, Steuersatz und Lieferdatum. Angaben zum Käufer (Name, Anschrift, UID) sind erst bei Rechnungen über 400 € brutto nötig." },
      en: { q: "Which details must a small-amount invoice (up to €400 gross) contain? Select all that apply.", o: ["Name and address of the seller", "Date of issue", "Total amount including VAT", "Buyer's VAT ID number", "Tax rate", "Name and address of the buyer"], e: "For a small-amount invoice the following are enough: seller, date, quantity/description, total amount incl. VAT, tax rate and date of delivery. Details about the buyer (name, address, VAT ID) are only needed on invoices above €400 gross." },
      hu: { q: "Milyen adatokat kell tartalmaznia egy egyszerűsített (kis összegű) számlának (bruttó 400 €-ig)? Válaszd ki az összes helyeset.", o: ["Az eladó neve és címe", "A kiállítás dátuma", "Az áfát is tartalmazó végösszeg", "A vevő közösségi adószáma", "Az adókulcs", "A vevő neve és címe"], e: "Az egyszerűsített számlán elég: eladó, dátum, mennyiség/megnevezés, áfát is tartalmazó végösszeg, adókulcs és a szállítás dátuma. A vevő adatai (név, cím, közösségi adószám) csak bruttó 400 € feletti számlán kötelezők." },
    },
    {
      type: "order", level: 1,
      de: { q: "Bringe die Schritte bei der Annahme einer Lieferung in die richtige Reihenfolge.", o: ["Produkt annehmen und prüfen", "Ware einlagern", "Rechnung prüfen", "Zahlung freigeben"], e: "Zuerst wird die Ware übernommen und auf Menge und Mängel geprüft, dann eingelagert. Erst danach wird die Rechnung mit Bestellung und Lieferung verglichen – und nur eine korrekte Rechnung wird zur Zahlung freigegeben." },
      en: { q: "Put the steps for accepting a delivery in the correct order.", o: ["Accept and check the product", "Store the goods", "Check the invoice", "Release the payment"], e: "First the goods are accepted and checked for quantity and defects, then stored. Only then is the invoice compared with the order and delivery – and only a correct invoice is released for payment." },
      hu: { q: "Állítsd helyes sorrendbe a szállítmány átvételének lépéseit.", o: ["A termék átvétele és ellenőrzése", "Az áru betárolása", "A számla ellenőrzése", "A fizetés jóváhagyása"], e: "Először átveszik az árut, és ellenőrzik a mennyiséget és a hibákat, majd betárolják. Csak ezután vetik össze a számlát a megrendeléssel és a szállítással – és csak a helyes számlát hagyják jóvá fizetésre." },
    },
    {
      type: "match", level: 2,
      de: { q: "Ordne jedes Schriftstück seiner Funktion zu.", p: [["Anfrage", "Käufer bittet unverbindlich um Infos/Angebot"], ["Angebot", "Verkäufer will zu genannten Bedingungen verkaufen"], ["Gegenangebot", "Käufer schlägt eigene Bedingungen vor"], ["Auftragsbestätigung", "Verkäufer wiederholt alle Bestelldaten"], ["Gegenschein", "Käufer bestätigt die Übernahme mit Unterschrift"]], e: "Anfrage (Käufer) ist unverbindlich, das Angebot (Verkäufer) verbindlich. Mit dem Gegenangebot ändert der Käufer Bedingungen, die Auftragsbestätigung soll Irrtümer vermeiden, und der unterschriebene Gegenschein beweist die Lieferung." },
      en: { q: "Match each document with its function.", p: [["Enquiry", "Buyer asks for info/offer without obligation"], ["Offer", "Seller wants to sell on the stated terms"], ["Counter-offer", "Buyer proposes his own terms"], ["Order confirmation", "Seller repeats all order details"], ["Counterfoil", "Buyer confirms receipt with a signature"]], e: "The enquiry (buyer) is non-binding, the offer (seller) binding. With a counter-offer the buyer changes terms, the order confirmation helps avoid mistakes, and the signed counterfoil proves delivery." },
      hu: { q: "Párosítsd az iratokat a funkciójukkal.", p: [["Ajánlatkérés", "A vevő kötelezettség nélkül információt/ajánlatot kér"], ["Ajánlat", "Az eladó a megadott feltételekkel akar eladni"], ["Ellenajánlat", "A vevő saját feltételeket javasol"], ["Megrendelés-visszaigazolás", "Az eladó megismétli az összes rendelési adatot"], ["Ellenlevél", "A vevő aláírással igazolja az átvételt"]], e: "Az ajánlatkérés (vevő) nem kötelező, az ajánlat (eladó) kötelező érvényű. Ellenajánlattal a vevő módosítja a feltételeket, a visszaigazolás a tévedéseket előzi meg, az aláírt ellenlevél pedig a szállítást bizonyítja." },
    },
    {
      type: "mc", level: 2, correctIndex: 2,
      de: { q: "Loopy braucht dringend Ostereier-Verpackungen. Anbieter A: 0,42 €/Stück, Lieferzeit 6 Wochen, oft unpünktlich. Anbieter B: 0,44 €/Stück, Lieferzeit 1 Woche, termintreu, 2 % Skonto. Ostern ist in 3 Wochen. Wen sollte Loopy wählen?", o: ["A, weil sein Stückpreis am niedrigsten von beiden ist", "A, weil man bei langer Lieferzeit später zahlt", "B, weil Lieferzeit und Termintreue wichtiger sind", "Keinen, weil man immer drei Angebote braucht"], e: "Wer nur Preise vergleicht, findet den billigsten Anbieter – entscheidend ist aber der beste Anbieter. A könnte vor Ostern gar nicht liefern. B ist pünktlich, schnell und durch 2 % Skonto praktisch genauso günstig." },
      en: { q: "Loopy urgently needs Easter egg packaging. Supplier A: €0.42/piece, delivery time 6 weeks, often late. Supplier B: €0.44/piece, delivery time 1 week, reliable, 2% cash discount. Easter is in 3 weeks. Whom should Loopy choose?", o: ["A, because its unit price is the lower of the two", "A, because with a long delivery time you pay later", "B, because delivery time and reliability matter more", "Neither, because you always need three offers"], e: "Comparing only prices finds the cheapest supplier – but what counts is the best supplier. A could not even deliver before Easter. B is punctual, fast and, thanks to the 2% cash discount, practically just as cheap." },
      hu: { q: "Loopynak sürgősen húsvéti tojáscsomagolásra van szüksége. A ajánlattevő: 0,42 €/db, szállítási idő 6 hét, gyakran késik. B ajánlattevő: 0,44 €/db, szállítási idő 1 hét, pontos, 2% skontó. Húsvét 3 hét múlva van. Kit válasszon Loopy?", o: ["A-t, mert az ő darabára a kettő közül alacsonyabb", "A-t, mert hosszú szállítási időnél később kell fizetni", "B-t, mert a szállítási idő és a pontosság fontosabb", "Egyiket sem, mert mindig három ajánlat kell"], e: "Aki csak az árakat hasonlítja össze, a legolcsóbb ajánlattevőt találja meg – a döntő azonban a legjobb ajánlattevő. A húsvét előtt nem is tudna szállítani. B pontos, gyors, és a 2% skontó miatt gyakorlatilag ugyanolyan olcsó." },
    },
    {
      type: "mc", level: 3, correctIndex: 2,
      de: { q: "Ein Lkw-Fahrer liefert 20 Kartons Kakaopulver an Loopys Candy Store. Zwei Kartons sind sichtbar eingedrückt und nass. Der Fahrer drängt, schnell zu unterschreiben. Was sollte die Mitarbeiterin tun?", o: ["Unterschreiben und den Schaden später per E-Mail melden", "Die Unterschrift verweigern und alle 20 Kartons zurückschicken", "Schaden auf Liefer- und Gegenschein vermerken, dann unterschreiben", "Unterschreiben und dafür die Rechnung einfach um 10 % kürzen"], e: "Erkennbare Mängel müssen sofort auf Liefer- und Gegenschein vermerkt werden – sonst bestätigt die Unterschrift eine einwandfreie Übernahme. Die mangelfreien Kartons sind vertragsgemäß und müssen angenommen werden; die Rechnung darf nur der Aussteller korrigieren." },
      en: { q: "A lorry driver delivers 20 boxes of cocoa powder to Loopy's Candy Store. Two boxes are visibly dented and wet. The driver urges her to sign quickly. What should the employee do?", o: ["Sign now and report the damage later by email", "Refuse to sign and send all 20 boxes back at once", "Note the damage on both delivery papers, then sign", "Sign and simply cut the invoice amount by 10%"], e: "Visible defects must be noted on the delivery note and counterfoil immediately – otherwise the signature confirms a flawless handover. The undamaged boxes conform to the contract and must be accepted; only the issuer may correct the invoice." },
      hu: { q: "Egy kamionsofőr 20 karton kakaóport szállít Loopy's Candy Store-nak. Két karton láthatóan be van nyomódva és nedves. A sofőr sürgeti, hogy gyorsan írja alá az átvételt. Mit tegyen a munkatárs?", o: ["Írja alá, és a kárt csak később jelentse e-mailben", "Tagadja meg az aláírást, és küldje vissza mind a 20 kartont", "Jegyezze fel a kárt mindkét szállítási okmányra, majd írja alá", "Írja alá, és egyszerűen csökkentse a számlát 10%-kal"], e: "A látható hibákat azonnal fel kell jegyezni a szállítólevélre és az ellenlevélre – különben az aláírás hibátlan átvételt igazol. A sértetlen kartonok szerződésszerűek, ezeket át kell venni; a számlát pedig csak a kiállítója javíthatja." },
    },
    {
      type: "number", level: 3, value: 387.6, tol: 0.01, unit: { de: "€", en: "€", hu: "€" },
      de: { q: "Ein Großhändler liefert Loopy 85 Rollen Geschenkband zu je 4,00 € netto. Vereinbart sind 5 % Rabatt, dazu kommen 20 % USt. Wie hoch ist der Rechnungsbetrag brutto?", e: "85 · 4,00 = 340,00 €; − 5 % Rabatt (17,00 €) = 323,00 € netto; + 20 % USt (64,60 €) = 387,60 € brutto. Da der Betrag unter 400 € brutto liegt, darf eine Kleinbetragsrechnung ausgestellt werden." },
      en: { q: "A wholesaler delivers 85 rolls of gift ribbon to Loopy at €4.00 net each. A 5% discount is agreed, and 20% VAT is added. What is the gross invoice amount?", e: "85 · 4.00 = €340.00; − 5% discount (€17.00) = €323.00 net; + 20% VAT (€64.60) = €387.60 gross. As the amount is below €400 gross, a small-amount invoice may be issued." },
      hu: { q: "Egy nagykereskedő 85 tekercs díszszalagot szállít Loopynak darabonként nettó 4,00 €-ért. 5% engedményben állapodtak meg, és ehhez jön 20% áfa. Mekkora a bruttó számlaösszeg?", e: "85 · 4,00 = 340,00 €; − 5% engedmény (17,00 €) = nettó 323,00 €; + 20% áfa (64,60 €) = bruttó 387,60 €. Mivel az összeg bruttó 400 € alatt van, egyszerűsített számla is kiállítható." },
    },
  ],

  "zahlungsformen-1jg": [
    {
      type: "tf", level: 1, correct: true,
      de: { q: "Bei einem Und-Konto dürfen die Kontoinhaber:innen nur gemeinsam über das Konto verfügen.", e: "Richtig: Beim Und-Konto müssen alle gemeinsam handeln. Beim Oder-Konto darf dagegen jede:r allein verfügen." },
      en: { q: "With an “and” account, the account holders may only operate the account jointly.", e: "True: with an “and” account all holders must act together. With an “or” account, by contrast, each holder may act alone." },
      hu: { q: "Az „és”-számla tulajdonosai csak együttesen rendelkezhetnek a számla felett.", e: "Igaz: az „és”-számlánál mindenkinek együtt kell eljárnia. A „vagy”-számlánál viszont mindegyik tulajdonos egyedül is rendelkezhet." },
    },
    {
      type: "tf", level: 2, correct: false,
      de: { q: "Eine zeichnungsberechtigte Person darf das Girokonto auch auflösen.", e: "Falsch: Zeichnungsberechtigte dürfen Geld abheben, einzahlen und Daueraufträge einrichten – das Konto löschen darf aber nur die verfügungsberechtigte Person (Inhaber:in)." },
      en: { q: "An authorised signatory may also close the current account.", e: "False: authorised signatories may withdraw and deposit money and set up standing orders – but only the person with full power of disposal (the account holder) may close the account." },
      hu: { q: "Az aláírási joggal rendelkező személy a folyószámlát meg is szüntetheti.", e: "Hamis: az aláírási jogosult pénzt vehet fel, befizethet és rendszeres átutalást állíthat be – a számlát azonban csak a rendelkezési jogosult (a tulajdonos) szüntetheti meg." },
    },
    {
      type: "tf", level: 2, correct: true,
      de: { q: "Für eine SEPA-Überweisung von Wien nach Oslo genügt die IBAN des Empfängers, ein BIC ist nicht nötig.", e: "Richtig: Norwegen gehört zum SEPA-Raum (EU plus u. a. Großbritannien, Norwegen, Island, Liechtenstein, Schweiz). Dort reicht die IBAN, und die Überweisung kostet gleich viel wie im Inland." },
      en: { q: "For a SEPA transfer from Vienna to Oslo the payee's IBAN is enough; no BIC is needed.", e: "True: Norway belongs to the SEPA area (EU plus the UK, Norway, Iceland, Liechtenstein, Switzerland and others). There the IBAN is enough, and the transfer costs the same as a domestic one." },
      hu: { q: "Egy Bécsből Oslóba indított SEPA-átutaláshoz elég a kedvezményezett IBAN-ja, BIC nem szükséges.", e: "Igaz: Norvégia a SEPA-térség része (EU, valamint többek között az Egyesült Királyság, Norvégia, Izland, Liechtenstein, Svájc). Ott elég az IBAN, és az átutalás ugyanannyiba kerül, mint belföldön." },
    },
    {
      type: "multi", level: 1, correct: [0, 2, 4],
      de: { q: "Welche Zahlungen eignen sich typischerweise für einen SEPA-Dauerauftrag? Wähle alle zutreffenden.", o: ["Monatliche Miete von 850 €", "Stromrechnung mit wechselnden Beträgen", "Gleichbleibende Kreditrate", "Handyrechnung nach Verbrauch", "Fixer Monatsbeitrag fürs Fitnessstudio"], e: "Ein Dauerauftrag passt für regelmäßige Zahlungen mit gleichem Betrag – der Zahler bestimmt. Wechselnde Beträge wie Strom oder verbrauchsabhängige Handyrechnungen zahlt man besser per SEPA-Lastschrift, bei der der Empfänger abbucht." },
      en: { q: "Which payments are typically suitable for a SEPA standing order? Select all that apply.", o: ["Monthly rent of €850", "Electricity bill with varying amounts", "Fixed loan instalment", "Mobile phone bill based on usage", "Fixed monthly gym fee"], e: "A standing order suits regular payments of the same amount – the payer decides. Varying amounts such as electricity or usage-based phone bills are better paid by SEPA direct debit, where the payee collects the money." },
      hu: { q: "Mely kifizetésekre alkalmas jellemzően a SEPA rendszeres átutalási megbízás? Válaszd ki az összes helyeset.", o: ["850 €-s havi lakbér", "Változó összegű villanyszámla", "Állandó összegű hiteltörlesztő részlet", "Fogyasztásfüggő telefonszámla", "Fix havi edzőtermi tagdíj"], e: "A rendszeres átutalás az azonos összegű, rendszeres kifizetésekhez illik – a fizető dönt. A változó összegeket, mint az áram vagy a fogyasztásfüggő telefonszámla, jobb SEPA beszedéssel fizetni, ahol a kedvezményezett szedi be a pénzt." },
    },
    {
      type: "multi", level: 2, correct: [0, 2, 4],
      de: { q: "Welche Aussagen zur Kreditkarte treffen zu? Wähle alle zutreffenden.", o: ["Die Umsätze werden gesammelt am Monatsende abgebucht", "Man bekommt sie schon ab 16 Jahren ohne Einkommen", "Online zahlt man mit Kartennummer, Ablaufdatum, Prüfziffer und 3D-Secure", "Bargeld abheben ist damit besonders günstig", "Man kann damit weltweit bezahlen"], e: "Die Kreditkarte funktioniert nach „pay later“, ist weltweit einsetzbar und wird online mit Kartendaten und 3D-Secure verwendet. Sie gibt es nur ab 18 mit regelmäßigem Einkommen, und Bargeldbehebungen damit sind teuer." },
      en: { q: "Which statements about the credit card are correct? Select all that apply.", o: ["Transactions are debited together at the end of the month", "You can get one from age 16 without income", "Online you pay with card number, expiry date, security code and 3D Secure", "Withdrawing cash with it is particularly cheap", "You can pay with it worldwide"], e: "The credit card works on a “pay later” basis, can be used worldwide and is used online with card details and 3D Secure. It is only available from 18 with a regular income, and cash withdrawals with it are expensive." },
      hu: { q: "Mely állítások igazak a hitelkártyára? Válaszd ki az összes helyeset.", o: ["A tranzakciókat összesítve a hónap végén terhelik", "Már 16 éves kortól, jövedelem nélkül is megkapható", "Online kártyaszámmal, lejárati dátummal, ellenőrző kóddal és 3D Secure-ral fizetünk", "Különösen olcsó vele készpénzt felvenni", "Világszerte lehet vele fizetni"], e: "A hitelkártya „pay later” elven működik, világszerte használható, online pedig a kártyaadatokkal és 3D Secure-ral fizetünk vele. Csak 18 éves kortól, rendszeres jövedelemmel kapható, és a készpénzfelvétel vele drága." },
    },
    {
      type: "order", level: 1,
      de: { q: "Bringe die Schritte einer Zahlung per Nachnahme in die richtige Reihenfolge.", o: ["Verkäufer schickt die Ware per Post oder Logistiker", "Zusteller übergibt die Ware nur gegen Bezahlung", "Zusteller überweist das Geld an den Verkäufer"], e: "Bei der Nachnahme bekommt der Käufer die Ware erst, wenn er beim Zusteller zahlt. Danach leitet der Zusteller das Geld an den Verkäufer weiter – so trägt der Verkäufer kein Zahlungsrisiko." },
      en: { q: "Put the steps of a cash-on-delivery payment in the correct order.", o: ["Seller sends the goods by post or logistics company", "Courier hands over the goods only against payment", "Courier transfers the money to the seller"], e: "With cash on delivery the buyer only gets the goods once he pays the courier. Then the courier passes the money on to the seller – so the seller bears no payment risk." },
      hu: { q: "Állítsd helyes sorrendbe az utánvétes fizetés lépéseit.", o: ["Az eladó postán vagy futárral elküldi az árut", "A kézbesítő csak fizetés ellenében adja át az árut", "A kézbesítő átutalja a pénzt az eladónak"], e: "Utánvétnél a vevő csak akkor kapja meg az árut, ha fizet a kézbesítőnek. Ezután a kézbesítő továbbítja a pénzt az eladónak – így az eladó nem visel fizetési kockázatot." },
    },
    {
      type: "match", level: 2,
      de: { q: "Ordne jedes Zahlungsmittel seiner Funktionsweise zu.", p: [["Debitkarte", "„pay now“ – sofort vom Konto abgebucht"], ["Kreditkarte", "„pay later“ – gesammelt am Monatsende"], ["Prepaidkarte", "„pay before“ – vorher aufgeladenes Guthaben"], ["Paysafecard", "16-stelliger PIN-Code, keine persönlichen Daten"], ["eps", "Überweisung mit E-Banking-Zugang direkt im Shop"]], e: "Debit-, Kredit- und Prepaidkarte unterscheiden sich darin, wann gezahlt wird: jetzt, später oder vorher. Paysafecard ist eine anonyme Wertkarte mit PIN-Code, eps eine Online-Überweisung aus dem eigenen E-Banking." },
      en: { q: "Match each means of payment with how it works.", p: [["Debit card", "“pay now” – debited from the account at once"], ["Credit card", "“pay later” – collected at the end of the month"], ["Prepaid card", "“pay before” – balance loaded in advance"], ["Paysafecard", "16-digit PIN code, no personal data"], ["eps", "Transfer via online banking directly in the shop"]], e: "Debit, credit and prepaid cards differ in when you pay: now, later or beforehand. Paysafecard is an anonymous voucher card with a PIN code, eps an online transfer from your own online banking." },
      hu: { q: "Párosítsd a fizetőeszközöket a működésükkel.", p: [["Betéti kártya", "„pay now” – azonnal terhelik a számlát"], ["Hitelkártya", "„pay later” – összesítve a hónap végén"], ["Feltöltős kártya", "„pay before” – előre feltöltött egyenleg"], ["Paysafecard", "16 jegyű PIN-kód, személyes adatok nélkül"], ["eps", "Átutalás netbankkal közvetlenül a webáruházból"]], e: "A betéti, a hitel- és a feltöltős kártya abban különbözik, mikor fizetünk: most, később vagy előre. A Paysafecard anonim értékkártya PIN-kóddal, az eps pedig online átutalás a saját netbankból." },
    },
    {
      type: "mc", level: 2, correctIndex: 1,
      de: { q: "Eine Kundin will in Loopys Candy Store einen Geschenkkorb um 62 € kontaktlos mit ihrer Debitkarte bezahlen. Was gilt?", o: ["Sie zahlt ohne PIN, weil kontaktlos nie eine PIN nötig ist", "Sie muss die PIN eingeben, weil der Betrag über 50 € liegt", "Kontaktlos ist über 50 € verboten, sie muss bar zahlen", "Sie muss statt der PIN den Beleg unterschreiben"], e: "Kontaktloses Zahlen (NFC) ohne PIN ist nur bis 50 € möglich. Bei 62 € ist die PIN-Eingabe nötig – zahlen kann sie mit der Debitkarte trotzdem." },
      en: { q: "A customer wants to pay €62 for a gift basket at Loopy's Candy Store contactlessly with her debit card. What applies?", o: ["She pays without a PIN, as contactless never needs a PIN", "She must enter her PIN because the amount is over €50", "Contactless is prohibited above €50, she must pay cash", "Instead of a PIN she must sign the receipt"], e: "Contactless payment (NFC) without a PIN is only possible up to €50. For €62 she has to enter her PIN – but she can still pay with the debit card." },
      hu: { q: "Egy vevő Loopy's Candy Store-ban egy 62 €-s ajándékkosarat szeretne érintéssel kifizetni a betéti kártyájával. Mi érvényes?", o: ["PIN nélkül fizet, mert érintéses fizetéshez sosem kell PIN", "Meg kell adnia a PIN-kódot, mert az összeg 50 € fölött van", "50 € fölött tilos az érintéses fizetés, készpénzzel kell fizetnie", "PIN helyett alá kell írnia a bizonylatot"], e: "Érintéses (NFC) fizetés PIN nélkül csak 50 €-ig lehetséges. 62 €-nál meg kell adni a PIN-kódot – a betéti kártyával ettől még fizethet." },
    },
    {
      type: "mc", level: 3, correctIndex: 1,
      de: { q: "Eine Kundin ohne eigenes Bankkonto bestellt bei Loopy per Nachnahme. Sie zahlt dem Zusteller bar, und das Geld wird auf Loopys Girokonto überwiesen. Welche Zahlungsart liegt vor?", o: ["Barzahlung, weil die Kundin Bargeld übergibt", "Halbbare Zahlung, weil nur einer ein Konto hat", "Bargeldlose Zahlung, weil Loopy eine Gutschrift erhält", "SEPA-Lastschrift, weil der Empfänger das Geld einzieht"], e: "Halbbar heißt: Nur einer der beiden Partner hat ein Konto – die Kundin zahlt bar, Loopy erhält das Geld aufs Konto. Reine Barzahlung wäre eine direkte Übergabe zwischen Schuldnerin und Gläubigerin, bargeldlos setzt voraus, dass beide ein Konto haben." },
      en: { q: "A customer without a bank account orders from Loopy cash on delivery. She pays the courier in cash, and the money is transferred to Loopy's current account. What type of payment is this?", o: ["Cash payment, because the customer hands over cash", "Semi-cash payment, as only one party has an account", "Cashless payment, because Loopy receives a credit", "SEPA direct debit, because the payee collects the money"], e: "Semi-cash means only one of the two parties has an account – the customer pays in cash, Loopy receives the money into her account. A pure cash payment would be a direct handover between debtor and creditor; cashless requires both to have an account." },
      hu: { q: "Egy bankszámlával nem rendelkező vevő utánvéttel rendel Loopytól. Készpénzzel fizet a kézbesítőnek, és a pénzt átutalják Loopy folyószámlájára. Milyen fizetési módról van szó?", o: ["Készpénzes fizetésről, mert a vevő készpénzt ad át", "Félkészpénzesről, mert csak az egyik félnek van számlája", "Készpénz nélküli fizetésről, mert Loopy jóváírást kap", "SEPA beszedésről, mert a kedvezményezett szedi be a pénzt"], e: "Félkészpénzes azt jelenti, hogy a két fél közül csak az egyiknek van számlája – a vevő készpénzzel fizet, Loopy a számlájára kapja a pénzt. A tisztán készpénzes fizetés az adós és a hitelező közötti közvetlen átadás, a készpénz nélküli pedig feltételezi, hogy mindkettőnek van számlája." },
    },
    {
      type: "mc", level: 3, correctIndex: 0,
      de: { q: "Loopy wechselt den Stromanbieter. Der alte Anbieter bucht die Stromkosten bisher per SEPA-Lastschrift ab. Wie beendet sie diese Zahlungen richtig?", o: ["Sie widerruft die Einzugsermächtigung beim Stromanbieter", "Sie löscht bei ihrer Bank den Dauerauftrag an den Anbieter", "Gar nicht – eine SEPA-Lastschrift ist unwiderruflich", "Sie lässt einfach ihr Konto ins Minus rutschen"], e: "Bei der Lastschrift erteilt der Zahler dem Empfänger eine Einzugsermächtigung (Mandat) – widerrufen wird sie daher beim Empfänger. Den Dauerauftrag richtet man dagegen bei der Bank ein und widerruft ihn auch dort; ein Konto im Minus kostet nur hohe Sollzinsen." },
      en: { q: "Loopy is switching electricity provider. The old provider has been collecting the electricity costs by SEPA direct debit. How does she end these payments correctly?", o: ["She revokes the direct debit mandate with the provider", "She deletes the standing order to the provider at her bank", "Not at all – a SEPA direct debit is irrevocable", "She simply lets her account go into overdraft"], e: "With a direct debit the payer gives the payee a mandate – so it is revoked with the payee. A standing order, by contrast, is set up with the bank and revoked there; an overdrawn account only costs high debit interest." },
      hu: { q: "Loopy áramszolgáltatót vált. A régi szolgáltató eddig SEPA beszedéssel szedte be az áramdíjat. Hogyan szünteti meg helyesen ezeket a fizetéseket?", o: ["Visszavonja a beszedési felhatalmazást az áramszolgáltatónál", "A bankjában törli a szolgáltató felé szóló rendszeres átutalást", "Sehogy – a SEPA beszedés visszavonhatatlan", "Egyszerűen hagyja, hogy a számlája mínuszba csússzon"], e: "Beszedésnél a fizető beszedési felhatalmazást (mandátumot) ad a kedvezményezettnek – ezért azt a kedvezményezettnél kell visszavonni. A rendszeres átutalást viszont a banknál állítják be és ott is vonják vissza; a mínuszos számla csak magas tartozási kamatba kerül." },
    },
    {
      type: "number", level: 3, value: 9, tol: 0.01, unit: { de: "€", en: "€", hu: "€" },
      de: { q: "Loopy hat ein ganzes Jahr lang 4.800 € auf ihrem Konto. Die Bank zahlt 0,25 % Habenzinsen p. a. Davon wird die KESt (25 %) abgezogen. Wie viel Zinsen bekommt Loopy tatsächlich gutgeschrieben?", e: "Habenzinsen: 4.800 · 0,25 % = 12,00 €. KESt: 25 % von 12,00 = 3,00 €. Gutschrift: 12,00 − 3,00 = 9,00 €. Die KESt wird von den Zinsen abgezogen, nicht vom Guthaben." },
      en: { q: "Loopy has €4,800 in her account for a whole year. The bank pays 0.25% credit interest p.a. Capital gains tax (KESt, 25%) is deducted from it. How much interest is actually credited to Loopy?", e: "Credit interest: 4,800 · 0.25% = €12.00. KESt: 25% of 12.00 = €3.00. Credited: 12.00 − 3.00 = €9.00. The tax is deducted from the interest, not from the balance." },
      hu: { q: "Loopy számláján egy teljes évig 4800 € van. A bank évi 0,25% betéti kamatot fizet, amelyből levonják a tőkehozadék-adót (KESt, 25%). Mennyi kamatot írnak jóvá ténylegesen Loopynak?", e: "Betéti kamat: 4800 · 0,25% = 12,00 €. Tőkehozadék-adó: 12,00 25%-a = 3,00 €. Jóváírás: 12,00 − 3,00 = 9,00 €. Az adót a kamatból vonják le, nem az egyenlegből." },
    },
  ],

  "unzuverlaessige-verkaeufer": [
    {
      type: "tf", level: 1, correct: false,
      de: { q: "Bei einem geringfügigen Mangel kann die Käuferin sofort die Auflösung des Vertrags verlangen.", e: "Falsch: Zuerst gibt es Verbesserung oder Austausch. Und selbst wenn das scheitert, bleibt bei einem geringfügigen Mangel nur die Preisminderung – eine Vertragsauflösung ist ausgeschlossen." },
      en: { q: "In the case of a minor defect, the buyer can immediately demand termination of the contract.", e: "False: first comes repair or replacement. And even if that fails, a minor defect only entitles the buyer to a price reduction – termination of the contract is excluded." },
      hu: { q: "Csekély hiba esetén a vevő azonnal követelheti a szerződés felbontását.", e: "Hamis: először kijavítás vagy csere jár. És ha ez nem sikerül, csekély hibánál akkor is csak árleszállítás jár – a szerződés felbontása kizárt." },
    },
    {
      type: "tf", level: 1, correct: false,
      de: { q: "Ein Elektrohändler darf in seinen AGB die Gewährleistung gegenüber Privatkund:innen ausschließen.", e: "Falsch: Bei B2C-Geschäften darf die Gewährleistung NICHT ausgeschlossen werden. Eine solche AGB-Klausel ist unwirksam." },
      en: { q: "An electronics retailer may exclude the statutory warranty for private customers in its terms and conditions.", e: "False: in B2C transactions the statutory warranty may NOT be excluded. Such a clause in the terms and conditions is invalid." },
      hu: { q: "Egy műszaki kereskedő az ÁSZF-ében kizárhatja a szavatosságot a magánvásárlókkal szemben.", e: "Hamis: B2C-ügyleteknél a szavatosság NEM zárható ki. Az ilyen ÁSZF-kikötés érvénytelen." },
    },
    {
      type: "tf", level: 3, correct: true,
      de: { q: "Auch nach Ablauf der Gewährleistungsfrist bleiben noch 3 Monate Zeit, um die Ansprüche vor Gericht geltend zu machen.", e: "Richtig: Der Mangel muss innerhalb der Gewährleistungsfrist auftreten. Danach gibt es noch eine Verjährungsfrist von 3 Monaten, um die Rechte gerichtlich durchzusetzen." },
      en: { q: "Even after the statutory warranty period has expired, there are still 3 months left to assert the claims in court.", e: "True: the defect must appear within the warranty period. After that there is a limitation period of 3 more months to enforce the rights in court." },
      hu: { q: "A szavatossági idő lejárta után még 3 hónap marad arra, hogy az igényeket bíróság előtt érvényesítsék.", e: "Igaz: a hibának a szavatossági időn belül kell jelentkeznie. Ezt követően még 3 hónapos elévülési idő áll rendelkezésre a jogok bírósági érvényesítésére." },
    },
    {
      type: "multi", level: 2, correct: [0, 1, 3],
      de: { q: "Welche Aussagen zur Produkthaftung treffen zu? Wähle alle zutreffenden.", o: ["Es haften Hersteller bzw. Importeur", "Sie gilt für Personen- und Sachschäden durch ein fehlerhaftes Produkt", "Sie ist freiwillig, ähnlich wie eine Garantie", "Bei Sachschäden gibt es einen Selbstbehalt von 500 €", "Sie ist im Konsumentenschutzgesetz (KSchG) geregelt"], e: "Die Produkthaftung ist gesetzlich (PHG) und trifft Hersteller/Importeur für Personen- und Sachschäden, mit 500 € Selbstbehalt bei Sachschäden. Freiwillig ist nur die Garantie, und das KSchG regelt die Gewährleistung, nicht die Produkthaftung." },
      en: { q: "Which statements about product liability are correct? Select all that apply.", o: ["The manufacturer or importer is liable", "It applies to personal injury and property damage caused by a defective product", "It is voluntary, similar to a guarantee", "For property damage there is a €500 deductible", "It is regulated in the Consumer Protection Act (KSchG)"], e: "Product liability is statutory (PHG) and makes the manufacturer/importer liable for personal injury and property damage, with a €500 deductible for property damage. Only a guarantee is voluntary, and the KSchG deals with the statutory warranty, not product liability." },
      hu: { q: "Mely állítások igazak a termékfelelősségre? Válaszd ki az összes helyeset.", o: ["A gyártó, illetve az importőr felel", "A hibás termék által okozott személyi és dologi károkra vonatkozik", "Önkéntes, a garanciához hasonlóan", "Dologi kárnál 500 € önrész van", "A fogyasztóvédelmi törvény (KSchG) szabályozza"], e: "A termékfelelősség törvényi (PHG), és a gyártót/importőrt terheli a személyi és dologi károkért, dologi kárnál 500 € önrésszel. Csak a garancia önkéntes, a KSchG pedig a szavatosságot szabályozza, nem a termékfelelősséget." },
    },
    {
      type: "multi", level: 3, correct: [0, 1, 2],
      de: { q: "Welche Aussagen zu den Gewährleistungsfristen sind richtig? Wähle alle zutreffenden.", o: ["Neuer Laptop: 2 Jahre ab Übergabe", "Eigentumswohnung: 3 Jahre", "Gebrauchtes Auto: 2 Jahre, auf 1 Jahr verkürzbar", "Arglistig verschwiegener Mangel: 5 Jahre", "Gebrauchte Sachen: immer nur 6 Monate"], e: "Bewegliche Sachen haben 2 Jahre (bei gebrauchten auf 1 Jahr verkürzbar), unbewegliche 3 Jahre. Bei arglistig verschwiegenen Mängeln beträgt die Frist 30 Jahre, nicht 5. Die 6 Monate betreffen die Beweislastumkehr nach ABGB, nicht die Gewährleistungsfrist." },
      en: { q: "Which statements about statutory warranty periods are correct? Select all that apply.", o: ["New laptop: 2 years from handover", "Owner-occupied flat: 3 years", "Used car: 2 years, can be shortened to 1 year", "Fraudulently concealed defect: 5 years", "Used goods: always only 6 months"], e: "Movable goods have 2 years (can be shortened to 1 year for used goods), immovable property 3 years. For fraudulently concealed defects the period is 30 years, not 5. The 6 months refer to the reversal of the burden of proof under the ABGB, not to the warranty period." },
      hu: { q: "Mely állítások helyesek a szavatossági határidőkről? Válaszd ki az összes helyeset.", o: ["Új laptop: 2 év az átadástól", "Öröklakás: 3 év", "Használt autó: 2 év, 1 évre csökkenthető", "Csalárdul elhallgatott hiba: 5 év", "Használt dolgok: mindig csak 6 hónap"], e: "Az ingó dolgokra 2 év vonatkozik (használtaknál 1 évre csökkenthető), az ingatlanokra 3 év. Csalárdul elhallgatott hibánál a határidő 30 év, nem 5. A 6 hónap az ABGB szerinti megfordított bizonyítási teherre vonatkozik, nem a szavatossági időre." },
    },
    {
      type: "order", level: 2,
      de: { q: "Loopy hat Verpackungen „innerhalb von 2 Wochen“ bestellt, der Lieferant liefert nicht. Bringe die Schritte bis zum Schadenersatz in die richtige Reihenfolge.", o: ["Vereinbarter ungefährer Liefertermin verstreicht", "Mahnung mit angemessener Nachfrist (meist 14 Tage)", "Nachfrist läuft ohne Lieferung ab", "Rücktritt und Deckungskauf bei einem anderen Lieferanten", "Mehrkosten als Schadenersatz vom Lieferanten fordern"], e: "Beim gewöhnlichen Termingeschäft treten die Rechtsfolgen erst nach einer Mahnung mit Nachfrist ein. Erst wenn diese verstrichen ist, kann Loopy zurücktreten und woanders kaufen; die Preisdifferenz verlangt sie (bei Verschulden) als Schadenersatz." },
      en: { q: "Loopy ordered packaging “within 2 weeks”, but the supplier does not deliver. Put the steps up to the claim for damages in the correct order.", o: ["The agreed approximate delivery date passes", "Reminder with a reasonable grace period (usually 14 days)", "The grace period expires without delivery", "Withdrawal and cover purchase from another supplier", "Claim the extra costs from the supplier as damages"], e: "In an ordinary forward transaction the legal consequences only apply after a reminder with a grace period. Only once it has expired can Loopy withdraw and buy elsewhere; she claims the price difference as damages (if the supplier is at fault)." },
      hu: { q: "Loopy „2 héten belül” rendelt csomagolóanyagot, de a beszállító nem szállít. Állítsd helyes sorrendbe a lépéseket a kártérítésig.", o: ["Eltelik a megállapodott hozzávetőleges szállítási határidő", "Felszólítás megfelelő póthatáridővel (általában 14 nap)", "A póthatáridő szállítás nélkül lejár", "Elállás és fedezeti vétel egy másik beszállítótól", "A többletköltség követelése kártérítésként a beszállítótól"], e: "Szokásos határidős ügyletnél a jogkövetkezmények csak póthatáridős felszólítás után állnak be. Csak ennek lejárta után állhat el Loopy, és vásárolhat máshol; az árkülönbözetet (vétkesség esetén) kártérítésként követeli." },
    },
    {
      type: "match", level: 1,
      de: { q: "Ordne jedes Beispiel der passenden Mangelart zu.", p: [["Glas ist bei der Lieferung zerbrochen", "Offener Mangel"], ["Elektronikfehler zeigt sich nach 3 Monaten", "Versteckter Mangel"], ["Verkäufer verschweigt bewusst einen Wasserschaden", "Arglistig verschwiegener Mangel"], ["Motor des Lieferwagens ist kaputt", "Wesentlicher Mangel"], ["Farbe weicht leicht von der Abbildung ab", "Geringfügiger Mangel"]], e: "Nach der Erkennbarkeit unterscheidet man offen, versteckt und arglistig verschwiegen, nach der Bedeutung geringfügig und wesentlich. Die Einteilung entscheidet z. B. darüber, ob eine Vertragsauflösung möglich ist und wie lange die Frist läuft." },
      en: { q: "Match each example with the right type of defect.", p: [["Glass is broken on delivery", "Obvious defect"], ["Electronic fault appears after 3 months", "Hidden defect"], ["Seller deliberately conceals water damage", "Fraudulently concealed defect"], ["The delivery van's engine is broken", "Material defect"], ["Colour differs slightly from the picture", "Minor defect"]], e: "By recognisability we distinguish obvious, hidden and fraudulently concealed defects; by significance minor and material ones. The classification decides, for example, whether the contract can be terminated and how long the period runs." },
      hu: { q: "Párosítsd a példákat a megfelelő hibafajtával.", p: [["Az üveg a kiszállításkor eltört", "Nyílt hiba"], ["Elektronikai hiba 3 hónap után jelentkezik", "Rejtett hiba"], ["Az eladó szándékosan elhallgat egy beázást", "Csalárdul elhallgatott hiba"], ["Tönkrement a kisteherautó motorja", "Lényeges hiba"], ["A szín kissé eltér a képtől", "Csekély hiba"]], e: "Felismerhetőség szerint nyílt, rejtett és csalárdul elhallgatott hibát, jelentőség szerint csekély és lényeges hibát különböztetünk meg. A besorolás dönti el például, hogy felbontható-e a szerződés, és meddig tart a határidő." },
    },
    {
      type: "mc", level: 3, correctIndex: 1,
      de: { q: "Frau Wallner kauft am 1. März bei einem Elektrohändler eine neue Kaffeemaschine. Mitte September fällt die Heizung aus. Der Händler sagt: „Nach 6 Monaten müssen Sie beweisen, dass der Fehler schon beim Kauf da war.“ Stimmt das?", o: ["Ja, nach 6 Monaten liegt die Beweislast immer bei der Käuferin", "Nein, bei B2C gilt 12 Monate die Vermutung zu ihren Gunsten", "Nein, denn der Händler muss während der ganzen 2 Jahre alles beweisen", "Ja, und nach 6 Monaten ist die Gewährleistung ohnehin abgelaufen"], e: "Für Verbrauchergeschäfte gilt nach dem VGG eine Beweislastumkehr von 12 Monaten: Der Händler muss beweisen, dass die Maschine bei Übergabe in Ordnung war. Die 6 Monate gelten nur nach ABGB (z. B. zwischen Privaten); die Gewährleistungsfrist selbst beträgt 2 Jahre." },
      en: { q: "On 1 March Ms Wallner buys a new coffee machine from an electronics retailer. In mid-September the heating element fails. The retailer says: “After 6 months you have to prove the fault was there when you bought it.” Is that right?", o: ["Yes, after 6 months the burden of proof is always on the buyer", "No, in B2C the presumption runs for 12 months in her favour", "No, because the retailer must prove everything for the full 2 years", "Yes, and after 6 months the warranty has expired anyway"], e: "For consumer contracts the VGG provides a 12-month reversal of the burden of proof: the retailer must prove the machine was fine at handover. The 6 months only apply under the ABGB (e.g. between private persons); the warranty period itself is 2 years." },
      hu: { q: "Wallnerné március 1-jén új kávéfőzőt vásárol egy műszaki kereskedőnél. Szeptember közepén elromlik a fűtőegység. A kereskedő azt mondja: „6 hónap után Önnek kell bizonyítania, hogy a hiba már a vásárláskor megvolt.” Igaza van?", o: ["Igen, 6 hónap után a bizonyítási teher mindig a vevőé", "Nem, B2C-ben 12 hónapig a vevő javára szól a vélelem", "Nem, mert a kereskedőnek a teljes 2 év alatt mindent bizonyítania kell", "Igen, és 6 hónap után a szavatosság amúgy is lejárt"], e: "Fogyasztói ügyleteknél a VGG szerint 12 hónapos a megfordított bizonyítási teher: a kereskedőnek kell bizonyítania, hogy a gép átadáskor rendben volt. A 6 hónap csak az ABGB szerint érvényes (pl. magánszemélyek között); maga a szavatossági idő 2 év." },
    },
    {
      type: "mc", level: 2, correctIndex: 3,
      de: { q: "Loopy erhält von einem Lieferanten eine Rechnung über 2.400 €, auf der die UID-Nummer des Lieferanten fehlt. Was sollte sie tun?", o: ["Die UID-Nummer selbst handschriftlich auf der Rechnung ergänzen", "Nichts – die UID-Nummer ist nur ein freiwilliger Zusatz", "Die Rechnung bezahlen und 20 % USt einfach nicht überweisen", "Beim Lieferanten schriftlich eine neue Rechnung anfordern"], e: "Nur der Aussteller darf eine Rechnung korrigieren – also stellt der Lieferant eine neue Rechnung aus. Fehlt ein UStG-Bestandteil wie die UID-Nummer, bekommt Loopy keinen Vorsteuerabzug; eigenmächtige Ergänzungen oder Kürzungen sind unzulässig." },
      en: { q: "Loopy receives an invoice for €2,400 from a supplier on which the supplier's VAT ID number is missing. What should she do?", o: ["Add the VAT ID number to the invoice herself by hand", "Nothing – the VAT ID number is only an optional extra", "Pay the invoice but simply not transfer the 20% VAT", "Ask the supplier in writing for a new invoice"], e: "Only the issuer may correct an invoice – so the supplier issues a new one. If a required element under the VAT Act such as the VAT ID is missing, Loopy cannot deduct input VAT; making her own additions or deductions is not allowed." },
      hu: { q: "Loopy egy beszállítótól 2400 €-s számlát kap, amelyről hiányzik a beszállító közösségi adószáma. Mit tegyen?", o: ["Írja rá ő maga kézzel a közösségi adószámot a számlára", "Semmit – a közösségi adószám csak önkéntes kiegészítés", "Fizesse ki a számlát, de a 20% áfát egyszerűen ne utalja át", "Kérjen írásban új, javított számlát a beszállítótól"], e: "Számlát csak a kiállítója javíthat – a beszállító tehát új számlát állít ki. Ha hiányzik egy áfatörvényi kötelező elem, például a közösségi adószám, Loopy nem élhet előzetesadó-levonással; az önhatalmú kiegészítés vagy csökkentés nem megengedett." },
    },
    {
      type: "number", level: 2, value: 120, tol: 0.01, unit: { de: "€", en: "€", hu: "€" },
      de: { q: "Loopy hat 200 kg Kakaobohnen zu 6,50 €/kg bestellt. Der Lieferant gerät schuldhaft in Lieferverzug, auch die Nachfrist verstreicht. Loopy tritt zurück und kauft die Bohnen woanders zu 7,10 €/kg. Wie viel Schadenersatz kann sie verlangen?", e: "Ursprünglich: 200 · 6,50 = 1.300 €. Deckungskauf: 200 · 7,10 = 1.420 €. Schadenersatz = Differenz: 1.420 − 1.300 = 120 €. Voraussetzung ist ein Verschulden des Lieferanten." },
      en: { q: "Loopy ordered 200 kg of cocoa beans at €6.50/kg. The supplier is culpably late, and the grace period also passes. Loopy withdraws and buys the beans elsewhere at €7.10/kg. How much can she claim in damages?", e: "Originally: 200 · 6.50 = €1,300. Cover purchase: 200 · 7.10 = €1,420. Damages = difference: 1,420 − 1,300 = €120. This requires the supplier to be at fault." },
      hu: { q: "Loopy 200 kg kakaóbabot rendelt 6,50 €/kg áron. A beszállító vétkesen késedelembe esik, és a póthatáridő is eltelik. Loopy eláll, és máshol 7,10 €/kg áron veszi meg a babot. Mennyi kártérítést követelhet?", e: "Eredetileg: 200 · 6,50 = 1300 €. Fedezeti vétel: 200 · 7,10 = 1420 €. Kártérítés = különbözet: 1420 − 1300 = 120 €. Feltétele, hogy a beszállító vétkes legyen." },
    },
  ],
}
